let allStaffCache = [];
  let allUsersCache = [];
  window.APP_USER = null; // Holds the logged-in session data

  // Returns "Full Name — Designation" for a user_id, falls back to email or ID
  function staffLabel(userId) {
    const s = allStaffCache.find(s => s.teacher_id === userId);
    if (s && s.full_name) return s.designation ? `${s.full_name} — ${s.designation}` : s.full_name;
    const u = allUsersCache.find(u => u.user_id === userId);
    return u ? u.email : userId;
  }

  // ══════════════════════════════════════════════════════
  //  THEME — admin-configurable, applied for all: page gradient, sidebar
  //  colors and a global font-size scale, all bundled into one preset so
  //  picking a theme re-skins the whole portal in one click. Custom mode
  //  lets an admin override every one of these independently instead of
  //  picking a bundled preset.
  // ══════════════════════════════════════════════════════
  // Sidebar gradients deliberately stay in "rich jewel-tone" territory (mid
  // lightness, real saturation at the top stop) rather than near-black —
  // at very low lightness every hue reads as indistinguishable charcoal, so
  // the whole point of a per-theme sidebar color is lost. Each one is
  // built top→bottom from a vivid, clearly-that-color stop down to a deep
  // (but not pitch-black) base, so switching themes is obviously visible
  // and each still feels premium rather than neon.
  const THEME_PRESETS = {
    aurora:    { name:'Aurora',    stops:['#eaf2ff','#f4f0ff','#fdf1f9','#eefcff','#eef4ff'], accents:['#6366f1','#38bdf8','#ec4899','#10b981'], sidebarBg:'linear-gradient(160deg,#2f2f7a 0%,#1c1a52 55%,#100e30 100%)', sidebarText:'#8b8fd6', sidebarTextHover:'#eef0ff', sidebarAccent:'#6366f1' },
    ocean:     { name:'Ocean',     stops:['#e0f2fe','#e6fffb','#eff6ff','#ecfeff','#e0f7fa'], accents:['#0ea5e9','#06b6d4','#3b82f6','#14b8a6'], sidebarBg:'linear-gradient(160deg,#0b6a92 0%,#084566 55%,#042235 100%)', sidebarText:'#6fc3e0', sidebarTextHover:'#e3f7ff', sidebarAccent:'#0ea5e9' },
    sunset:    { name:'Sunset',    stops:['#fff1e6','#ffe9ef','#fef3c7','#ffe4e6','#fff7ed'], accents:['#fb923c','#f43f5e','#f59e0b','#ec4899'], sidebarBg:'linear-gradient(160deg,#9c2f56 0%,#6b1d3d 55%,#340e1e 100%)', sidebarText:'#e3a0b5', sidebarTextHover:'#ffe9f0', sidebarAccent:'#f43f5e' },
    forest:    { name:'Forest',    stops:['#ecfdf5','#f0fdf4','#f7fee7','#ecfccb','#effdf5'], accents:['#10b981','#22c55e','#84cc16','#14b8a6'], sidebarBg:'linear-gradient(160deg,#187347 0%,#0f4c2f 55%,#082e1c 100%)', sidebarText:'#7fd6a6', sidebarTextHover:'#e6fbef', sidebarAccent:'#22c55e' },
    lavender:  { name:'Lavender',  stops:['#f5f3ff','#faf5ff','#fdf4ff','#f3e8ff','#f5f3ff'], accents:['#8b5cf6','#a855f7','#d946ef','#6366f1'], sidebarBg:'linear-gradient(160deg,#6d28d9 0%,#471f96 55%,#241049 100%)', sidebarText:'#c4a8f0', sidebarTextHover:'#f4ecff', sidebarAccent:'#a855f7' },
    blossom:   { name:'Blossom',   stops:['#fff1f2','#fdf2f8','#fce7f3','#ffe4e6','#fff1f2'], accents:['#fb7185','#ec4899','#f472b6','#e11d48'], sidebarBg:'linear-gradient(160deg,#af1f63 0%,#761541 55%,#3b0a21 100%)', sidebarText:'#f0a3c6', sidebarTextHover:'#ffe9f4', sidebarAccent:'#ec4899' },
    graphite:  { name:'Graphite',  stops:['#f8fafc','#eef2f7','#f1f5f9','#e9eef5','#f8fafc'], accents:['#64748b','#475569','#94a3b8','#334155'], sidebarBg:'linear-gradient(160deg,#48566e 0%,#2e3849 55%,#161c26 100%)', sidebarText:'#a9b6c8', sidebarTextHover:'#f4f7fb', sidebarAccent:'#94a3b8' },
    midnight:  { name:'Midnight',  stops:['#eef2ff','#e8f4ff','#eefcff','#f0f5ff','#e6f7ff'], accents:['#22d3ee','#38bdf8','#818cf8','#2dd4bf'], sidebarBg:'linear-gradient(160deg,#0e8fa8 0%,#0a5266 55%,#020617 100%)', sidebarText:'#7fe6ea', sidebarTextHover:'#e6feff', sidebarAccent:'#22d3ee' },
    crimson:   { name:'Crimson',   stops:['#fff5f5','#fff0f0','#fef2f2','#fff1f2','#fef2f2'], accents:['#dc2626','#ef4444','#f97316','#b91c1c'], sidebarBg:'linear-gradient(160deg,#b3251f 0%,#791a16 55%,#3a0b09 100%)', sidebarText:'#eb9c98', sidebarTextHover:'#ffeceb', sidebarAccent:'#ef4444' },
    amber:     { name:'Amber',     stops:['#fffbeb','#fefce8','#fff7ed','#fefce8','#fffbeb'], accents:['#d97706','#f59e0b','#eab308','#b45309'], sidebarBg:'linear-gradient(160deg,#a85a0a 0%,#733d08 55%,#3a1f04 100%)', sidebarText:'#eab873', sidebarTextHover:'#fff2dc', sidebarAccent:'#f59e0b' },
    emerald:   { name:'Emerald',   stops:['#ecfdf5','#f0fdfa','#effdf5','#ecfeff','#f0fdf9'], accents:['#059669','#0d9488','#10b981','#0891b2'], sidebarBg:'linear-gradient(160deg,#04795c 0%,#03513e 55%,#022c22 100%)', sidebarText:'#6fd9bd', sidebarTextHover:'#e2fbf3', sidebarAccent:'#0d9488' },
    royal:     { name:'Royal',     stops:['#f5f3ff','#f3e8ff','#ede9fe','#f5f3ff','#efe8ff'], accents:['#7c3aed','#6d28d9','#9333ea','#4c1d95'], sidebarBg:'linear-gradient(160deg,#453ee0 0%,#2c26a3 55%,#150f56 100%)', sidebarText:'#a9a3f2', sidebarTextHover:'#ecebff', sidebarAccent:'#7c3aed' },
    slate:     { name:'Slate Light', stops:['#ffffff','#f8fafc','#f1f5f9','#f8fafc','#ffffff'], accents:['#334155','#475569','#0f172a','#64748b'], sidebarBg:'#ffffff', sidebarText:'#64748b', sidebarTextHover:'#0f172a', sidebarAccent:'#334155' },
    rosegold:  { name:'Rose Gold', stops:['#fff5f7','#fff7ed','#fef6f0','#fff1f2','#fff8f3'], accents:['#e8998d','#d4a373','#f2b8a0','#c97b63'], sidebarBg:'linear-gradient(160deg,#b5594a 0%,#7d3b30 55%,#3f1e18 100%)', sidebarText:'#eeb3a5', sidebarTextHover:'#fff0eb', sidebarAccent:'#e8998d' },
  };
  const FONT_SCALES = {
    compact:     { name:'Compact',      size:'87.5%' },
    comfortable: { name:'Comfortable',  size:'100%' },
    large:       { name:'Large',        size:'112.5%' },
    xlarge:      { name:'Extra Large',  size:'125%' },
  };
  // Every family here is already loaded via the single combined Google
  // Fonts @import in styles.css — adding a new option means adding it to
  // BOTH that import and this list.
  const FONT_FAMILIES = {
    inter:      { name:'Inter',            stack:"'Inter', sans-serif" },
    poppins:    { name:'Poppins',          stack:"'Poppins', sans-serif" },
    manrope:    { name:'Manrope',          stack:"'Manrope', sans-serif" },
    outfit:     { name:'Outfit',           stack:"'Outfit', sans-serif" },
    jakarta:    { name:'Plus Jakarta Sans',stack:"'Plus Jakarta Sans', sans-serif" },
    nunito:     { name:'Nunito',           stack:"'Nunito', sans-serif" },
    worksans:   { name:'Work Sans',        stack:"'Work Sans', sans-serif" },
    lexend:     { name:'Lexend',           stack:"'Lexend', sans-serif" },
  };
  const DEFAULT_THEME = { mode:'preset', preset:'aurora', fontScale:'comfortable', fontFamily:'inter' };
  window.APP_THEME = DEFAULT_THEME;

  function _hexToRgba(hex, a) {
    let h = String(hex || '').replace('#','');
    if (h.length === 3) h = h.split('').map(x => x + x).join('');
    const n = parseInt(h || '888888', 16);
    return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;
  }

  // Blends hexB into hexA by ratio t (0..1) — used to derive the main
  // content area's heading/subtext tint from each theme's own accent color,
  // without needing 14 hand-authored extra hex values per preset.
  function _mixHex(hexA, hexB, t) {
    const toRgb = hex => {
      let h = String(hex || '').replace('#','');
      if (h.length === 3) h = h.split('').map(x => x + x).join('');
      const n = parseInt(h || '888888', 16);
      return [(n>>16)&255, (n>>8)&255, n&255];
    };
    const a = toRgb(hexA), b = toRgb(hexB);
    const mix = (i) => Math.round(a[i] + (b[i] - a[i]) * t);
    return `rgb(${mix(0)},${mix(1)},${mix(2)})`;
  }

  function _themeColors(theme) {
    const p = THEME_PRESETS[(theme && theme.preset) || 'aurora'] || THEME_PRESETS.aurora;
    if (theme && theme.mode === 'custom' && Array.isArray(theme.stops) && theme.stops.length) {
      return {
        stops: theme.stops,
        accents: (theme.accents && theme.accents.length) ? theme.accents : theme.stops,
        sidebarBg: theme.sidebarBg || p.sidebarBg,
        sidebarText: theme.sidebarText || p.sidebarText,
        sidebarTextHover: theme.sidebarTextHover || p.sidebarTextHover,
        sidebarAccent: theme.sidebarAccent || p.sidebarAccent,
      };
    }
    return { stops: p.stops, accents: p.accents, sidebarBg: p.sidebarBg, sidebarText: p.sidebarText, sidebarTextHover: p.sidebarTextHover, sidebarAccent: p.sidebarAccent };
  }

  function applyTheme(theme) {
    const { stops, accents, sidebarBg, sidebarText, sidebarTextHover, sidebarAccent } = _themeColors(theme);
    const n = Math.max(stops.length, 2);
    const stopStr = stops.map((c,i) => `${c} ${Math.round(i/(n-1)*100)}%`).join(', ');
    const bg = `linear-gradient(135deg, ${stopStr})`;
    const pos    = ['10% 12%','92% 8%','85% 92%','18% 95%'];
    const sizes  = ['42rem 42rem','38rem 38rem','46rem 46rem','34rem 34rem'];
    const alphas = [0.18, 0.16, 0.12, 0.12];
    const glow = accents.slice(0,4).map((c,i) =>
      `radial-gradient(${sizes[i]} at ${pos[i]}, ${_hexToRgba(c, alphas[i])}, transparent 62%)`).join(', ');
    // Resting (non-hover/non-active) nav text used each preset's raw
    // sidebarText, which several presets tuned quite dim against their own
    // dark gradient for a subdued look — too low-contrast to read
    // comfortably. Blended halfway toward that same preset's own
    // sidebarTextHover instead of hand-retuning 14 presets' hex values —
    // brighter and still on-theme, while the hover/active state (full
    // sidebarTextHover) stays visibly more prominent.
    const brightSidebarText = _mixHex(sidebarText, sidebarTextHover, 0.55);
    const root = document.documentElement.style;
    root.setProperty('--app-bg', bg);
    root.setProperty('--app-glow', glow);
    root.setProperty('--sidebar-bg', sidebarBg);
    root.setProperty('--sidebar-text', brightSidebarText);
    root.setProperty('--sidebar-text-hover', sidebarTextHover);
    root.setProperty('--sidebar-icon-color', brightSidebarText);
    root.setProperty('--sidebar-accent-1', sidebarAccent);
    root.setProperty('--sidebar-accent-2', sidebarAccent);
    root.setProperty('--sidebar-accent-soft-1', _hexToRgba(sidebarAccent, 0.22));
    root.setProperty('--sidebar-accent-soft-2', _hexToRgba(sidebarAccent, 0.14));
    root.setProperty('--sidebar-accent-glow', _hexToRgba(sidebarAccent, 0.18));
    root.setProperty('--sidebar-accent-text', sidebarTextHover);
    root.setProperty('--sidebar-section-label', _hexToRgba(sidebarTextHover, 0.55));
    // Main content headings/subtext pick up a subtle tint of the theme's own
    // accent too — mostly neutral so contrast on the white/glass view cards
    // never suffers, but visibly shifting hue as the theme changes.
    root.setProperty('--view-heading', _mixHex('#0f172a', sidebarAccent, 0.22));
    root.setProperty('--view-subtext', _mixHex('#94a3b8', sidebarAccent, 0.4));
    document.documentElement.style.fontSize = (FONT_SCALES[(theme && theme.fontScale)] || FONT_SCALES.comfortable).size;
    root.setProperty('--app-font', (FONT_FAMILIES[(theme && theme.fontFamily)] || FONT_FAMILIES.inter).stack);
    window.APP_THEME = theme || DEFAULT_THEME;
  }

  function loadAndApplyTheme() {
    google.script.run.withSuccessHandler(settings => {
      const t = settings && settings.theme_gradient;
      applyTheme((t && (t.preset || (t.stops && t.stops.length))) ? t : DEFAULT_THEME);
    }).withFailureHandler(() => {}).getSystemSettings();
  }

  document.addEventListener('DOMContentLoaded', () => {
    // Warm up Vercel serverless function immediately so login isn't delayed by cold start.
    // getSystemSettings is lightweight and also applies the saved gradient theme on the login screen.
    loadAndApplyTheme();

    const savedId   = localStorage.getItem('ccpc_user_id');
    const savedPass = localStorage.getItem('ccpc_pass');
    console.log('[CCPC] Saved session:', savedId ? 'found (' + savedId + ')' : 'none');

    if (savedId && savedPass) {
      const btn = document.querySelector('#loginForm button[type="submit"]');
      if (btn) { btn.textContent = 'Signing in…'; btn.disabled = true; }
      performLogin(savedId, savedPass, true);
    }
    initLoginForm();
    _watchForAutofilledSearchFields();
  });

  // Some browsers (observed in Microsoft Edge) still populate a freshly-
  // rendered search field with the logged-in user's own saved info — their
  // ID, in this app's case — even with type="search" plus a full
  // autocomplete="off"/autocorrect/autocapitalize/spellcheck/unique-name
  // treatment, which is normally enough to opt a field out of Chrome's own
  // autofill candidate pool. Rather than chase per-browser attribute
  // quirks further, this watches every input[type="search"] as it's
  // inserted into the DOM (this app never has one before login) and wipes
  // any value found on it shortly after insertion — at that exact moment
  // the user cannot have typed anything yet, so any non-empty value can
  // only be autofill. Checked at three points (next frame, 250ms, 700ms)
  // since observed autofill timing varies. Re-fires the field's own
  // oninput handler after clearing so a search/filter that already ran
  // against the phantom value gets corrected back to "no filter" too.
  function _scrubAutofilledValue(el) {
    // Belt-and-suspenders: most browsers never offer autofill for a readonly
    // field at all, so lock it until the user's first real interaction —
    // this alone stops the vast majority of cases (incl. the delayed ones
    // the timed scrub below can still miss on a slower autofill provider).
    el.readOnly = true;
    let interacted = false;
    const unlock = () => {
      interacted = true; // once real interaction happens, a later scrub must never wipe what the user typed themselves
      el.readOnly = false;
      el.removeEventListener('focus', unlock);
      el.removeEventListener('mousedown', unlock);
      el.removeEventListener('touchstart', unlock);
    };
    el.addEventListener('focus', unlock);
    el.addEventListener('mousedown', unlock);
    el.addEventListener('touchstart', unlock);
    const scrub = () => { if (!interacted && el.value) { el.value = ''; el.dispatchEvent(new Event('input', { bubbles: true })); } };
    requestAnimationFrame(scrub);
    setTimeout(scrub, 250);
    setTimeout(scrub, 700);
    setTimeout(scrub, 1500);
    setTimeout(scrub, 3000);
  }
  // type="number" isn't covered by the type="search" selector below, and
  // the same browser-side autofill (logged-in user's own ID landing in an
  // unrelated field) was reported on a Weight% number input too. Can't just
  // widen the selector to every input[type="number"] app-wide though —
  // plenty of number fields (Marks Entry, the existing-component edit
  // cells) legitimately pre-fill with real saved data on render, and the
  // scrub below would wipe that, mistaking real data for autofill. Instead
  // this is opt-in: a field that should always start blank marks itself
  // with data-autofill-guard, and only those get watched alongside
  // type="search" (which is always blank-by-default in this app already).
  const _AUTOFILL_GUARD_SELECTOR = 'input[type="search"], input[data-autofill-guard]';
  function _watchForAutofilledSearchFields() {
    const root = document.body;
    if (!root || root._autofillGuardInstalled) return;
    root._autofillGuardInstalled = true;
    new MutationObserver(mutations => {
      mutations.forEach(m => m.addedNodes.forEach(node => {
        if (node.nodeType !== 1) return;
        if (node.matches && node.matches(_AUTOFILL_GUARD_SELECTOR)) _scrubAutofilledValue(node);
        if (node.querySelectorAll) node.querySelectorAll(_AUTOFILL_GUARD_SELECTOR).forEach(_scrubAutofilledValue);
      }));
    }).observe(root, { childList: true, subtree: true });
  }

  let _loadingTimer = null;
  function showLoading(show) {
    const el = document.getElementById('loading');
    if (!el) return;
    el.classList.toggle('hidden', !show);
    clearTimeout(_loadingTimer);
    if (show) {
      // Longer than the shim's own 25s fetch-abort timeout (shim.js), so a
      // slow request's real failure handler (with an actual error message)
      // gets to fire and hide this first — this is only the last-resort
      // backstop for a request that never calls either handler at all.
      _loadingTimer = setTimeout(() => {
        el.classList.add('hidden');
        console.warn('[CCPC] Loading spinner auto-hidden after timeout');
      }, 30000);
    }
  }

  // --- AUTHENTICATION ---
  function initLoginForm() {
    const form = document.getElementById('loginForm');
    if (form) {
      form.onsubmit = (e) => {
        e.preventDefault();
        performLogin(document.getElementById('loginId').value, document.getElementById('loginPass').value, false);
      };
    }
  }

  function performLogin(id, pass, isAuto) {
    const err     = document.getElementById('loginError');
    const loginId = document.getElementById('loginId');
    const loginPw = document.getElementById('loginPass');
    const btn     = document.querySelector('#loginForm button[type="submit"]');
    if (err) err.classList.add('hidden');
    showLoading(true);

    function restoreBtn() {
      if (btn) { btn.textContent = 'Enter Dashboard'; btn.disabled = false; }
    }

    google.script.run
      .withSuccessHandler(res => {
        showLoading(false);
        restoreBtn();
        if (res && res.success) {
          window.APP_USER    = res;
          window.USER_ROLES  = res.roles || [res.role];
          window.ACTIVE_ROLE = res.role;
          window.USER_ROLE   = res.role;
          if (res.profile) window._loginProfile = res.profile; // pre-loaded scalar profile
          // window._loginProfile is a ONE-SHOT cache — openMyProfile() nulls
          // it out the moment "My Profile" is viewed once (see ~952 below),
          // since that was its only intended consumer. Anything else reading
          // it later in the session (e.g. the lesson-plan print header's
          // "Name:" field) would silently go blank the first time a teacher
          // visits their own profile. window._myProfileStable is a second,
          // NEVER-cleared copy fetched independently right here so print/
          // export always has a name to show regardless of what else in the
          // session has consumed the one-shot cache.
          google.script.run.withSuccessHandler(p => { window._myProfileStable = p; }).withFailureHandler(() => {}).getMyProfile(res.email, res.user_id);
          localStorage.setItem('ccpc_user_id', id);
          localStorage.setItem('ccpc_pass', pass);
          // Login screen only ever gets hidden (never unmounted), so its
          // password field stays live in the DOM for the whole session —
          // browsers were tracking it and misfiring "Save password?" on
          // totally unrelated later input (e.g. typing into a search box).
          // Clearing the fields the moment they're no longer needed stops
          // that stale value from being tracked.
          if (loginId) loginId.value = '';
          if (loginPw) loginPw.value = '';
          launchDashboard();
        } else if (isAuto) {
          if (loginId) loginId.value = id;
          if (loginPw) loginPw.value = pass;
        } else {
          localStorage.removeItem('ccpc_user_id');
          localStorage.removeItem('ccpc_pass');
          if (err) err.classList.remove('hidden');
        }
      })
      .withFailureHandler((e) => {
        showLoading(false);
        restoreBtn();
        if (isAuto) {
          if (loginId) loginId.value = id;
          if (loginPw) loginPw.value = pass;
        } else if (err) {
          err.textContent = 'Connection error — please try again.';
          err.classList.remove('hidden');
        }
      })
      .loginAndGetProfile(id, pass);
  }

  // #login-screen holds #loginId (autocomplete="username") and #loginPass
  // (autocomplete="current-password") — correctly tagged so Chrome's
  // password manager can save/offer real login credentials. The problem:
  // launchDashboard() used to only CSS-hide this form, leaving it live in
  // the DOM for the whole admin session. Chrome's autofill isn't scoped to
  // visible elements — with a saved credential for this origin, it kept
  // offering that saved username into unrelated text fields elsewhere on
  // the page (e.g. Exams' "Medium" field), and no amount of autocomplete
  // tweaking on the TARGET fields fixed it, because the trigger is this
  // still-present SOURCE form. Detaching it from the document entirely
  // (not just hiding it) removes it from Chrome's live-page analysis;
  // logout() re-inserts the exact same node so the login form still works.
  let _detachedLoginScreen = null;

  // Only meaningful inside the packaged native app, where this portal and
  // the student portal are the SAME installed app switching which live URL
  // its WebView is pointed at — navigating like this keeps this origin's
  // localStorage/session untouched, so coming back later doesn't require
  // logging in again. Irrelevant (and hidden) in a normal browser tab.
  function switchToStudentPortal() {
    window.location.href = 'https://ccpc-portal.vercel.app';
  }
  (function () {
    if (window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()) {
      document.addEventListener('DOMContentLoaded', () => {
        const btn = document.getElementById('switch-portal-btn');
        if (btn) btn.classList.remove('hidden');
      });
    }
  })();

  function logout() {
    if (window.confirm("Are you sure you want to sign out?")) {
      localStorage.removeItem('ccpc_user_id');
      localStorage.removeItem('ccpc_pass');
      window.APP_USER = null;
      window.USER_ROLE = null;
      window.removeEventListener('hashchange', _routeByHash);
      _destroyRealtime();
      history.replaceState(null, '', window.location.pathname);
      if (_detachedLoginScreen) { document.body.appendChild(_detachedLoginScreen); _detachedLoginScreen = null; }
      document.getElementById('login-screen').classList.remove('hidden');
      document.getElementById('app-screen').classList.add('hidden');
      document.getElementById('view-container').innerHTML = '';
    }
  }

  // --- MOBILE SIDEBAR TOGGLE ---
  function openMobileSidebar() {
    const sidebar = document.getElementById('main-sidebar');
    const overlay = document.getElementById('sidebar-overlay');
    if (sidebar) sidebar.classList.remove('-translate-x-full');
    if (overlay) overlay.classList.remove('hidden');
  }

  function closeMobileSidebar() {
    const sidebar = document.getElementById('main-sidebar');
    const overlay = document.getElementById('sidebar-overlay');
    if (sidebar) sidebar.classList.add('-translate-x-full');
    if (overlay) overlay.classList.add('hidden');
  }

  function toggleSidebar() {
    const sidebar = document.getElementById('main-sidebar');
    if (!sidebar) return;
    sidebar.classList.toggle('sidebar-collapsed');
    const icon = document.getElementById('toggle-icon');
    if (icon) {
      const isCollapsed = sidebar.classList.contains('sidebar-collapsed');
      icon.setAttribute('data-lucide', isCollapsed ? 'chevron-right' : 'chevron-left');
      lucide.createIcons();
    }
    localStorage.setItem('sidebar_collapsed', sidebar.classList.contains('sidebar-collapsed'));
  }

  // --- MOBILE HARDWARE/GESTURE BACK BUTTON ---
  // Two things Back should do on a phone instead of its browser default of
  // leaving the app/page entirely:
  //   1. Close whatever modal/drawer is open (see _modalBackStack below).
  //   2. Otherwise, if inside any module (not already on the app-launcher
  //      Home screen), navigate to Home — the same thing tapping the
  //      top-bar's own back arrow already does (_mobileTopBarNavClick),
  //      reused here rather than reimplemented, so both stay consistent
  //      (e.g. a Student Portal sub-view's one-level-at-a-time behavior
  //      via _openStudentPortalMobileMenu is automatically respected).
  // Both push a history entry when they become "active" and consume it via
  // popstate; checked in that order on every Back press since a modal open
  // while inside a module should close the modal first, not jump home in
  // the same press. Once on Home with nothing open, Back has nothing left
  // to intercept and falls through to the browser's normal behavior — the
  // in-app back arrow itself is gone by then too (_syncMobileTopBarIcon
  // swaps it for the menu icon), so there's nothing on screen implying
  // Back should do anything else at that point either.
  const _modalBackStack = []; // [{el}], in the order modals were opened
  let _mobileHomeGuardActive = false;

  function _isTrackedModalId(id) { return !!id && (/(Modal|Overlay)$/.test(id) || id === 'main-sidebar'); }
  function _isModalOpen(el) {
    return el.id === 'main-sidebar' ? !el.classList.contains('-translate-x-full') : !el.classList.contains('hidden');
  }
  function _genericCloseModal(el) {
    if (!el || !el.isConnected) return;
    if (el.id === 'main-sidebar') { closeMobileSidebar(); return; }
    // Just re-hide it (app.html's global .hidden{display:none!important}
    // covers every modal variant, including the ones normally toggled via
    // a "flex" class rather than "hidden") — deliberately never el.remove()
    // here even for modals whose OWN close normally does that (they always
    // remove-then-recreate on their next open anyway, so a stale hidden
    // node left behind by a back-button close is harmless and gets cleaned
    // up then); removing a modal that's meant to persist and just toggle
    // visibility (e.g. lpJsonEditModal) would instead break its next open —
    // a getElementById on a since-removed id returning null.
    el.classList.add('hidden');
  }
  function _onModalOpened(el) {
    if (_modalBackStack.some(x => x.el === el)) return;
    history.pushState({ _modalGuard: true }, '');
    _modalBackStack.push({ el });
  }
  function _onModalClosed(el) {
    const idx = _modalBackStack.findIndex(x => x.el === el);
    if (idx === -1) return; // already popped by the popstate handler below
    _modalBackStack.splice(idx, 1);
    // Closed by something other than the back button (its own X/Cancel/
    // outside-click) — the history entry pushed when it opened is now
    // stale, but it's deliberately left in place rather than consumed with
    // history.back(): if this was the very first thing opened in this page
    // load (nothing else pushed earlier this session), going back would
    // navigate past the app's own starting point entirely — out of the
    // SPA, not just closing the modal — which is worse than the minor cost
    // of one harmless extra no-op Back press later (the stale entry has no
    // tracked modal/guard left to act on, so popping it here does nothing
    // and the press after it behaves normally).
  }

  // Called from setActiveNavLink (the true universal choke point every
  // module load already runs through) — pushes the Home-guard entry the
  // first time a mobile session leaves Home, and consumes it (silently, if
  // reached by something other than the back button) once it returns.
  function _trackMobileHomeGuard(onHome) {
    if (window.innerWidth >= 768) return; // desktop: Back should behave normally, no guard
    if (!onHome) {
      if (!_mobileHomeGuardActive) { history.pushState({ _homeGuard: true }, ''); _mobileHomeGuardActive = true; }
    } else if (_mobileHomeGuardActive) {
      // Reached Home by tapping the in-app back arrow (not the hardware/
      // gesture Back button) — just drop the flag, deliberately WITHOUT
      // history.back(): if this module was the very first thing loaded
      // this page load (e.g. a refresh restoring the last-open module,
      // which this app explicitly supports — see _routeByHash), there is
      // no earlier same-session Home entry to land on, and history.back()
      // would navigate straight out of the app instead. That previously
      // made the in-app back arrow appear to "not work" (or worse, exit
      // the app) the moment it was tapped from a freshly-loaded module.
      // The pushed entry is left stale in the browser's history; the only
      // cost is one harmless no-op Back press later, never a broken one.
      _mobileHomeGuardActive = false;
    }
  }

  // Mobile drill-down stack for multi-level tile grids that live INSIDE a
  // single module rather than being separate modules of their own — e.g.
  // Inventory Admin's grid → section, and Settings' category grid → entity
  // table. Same push-a-history-entry-consume-via-popstate shape as the
  // modal/home-guard stacks above, checked in between them (a modal open
  // should still close first; a drill-down level should still close before
  // falling all the way back to Home) so Back steps out one level at a
  // time instead of jumping straight to Home from three levels deep.
  const _invNavStack = []; // [fn, ...] — each entry closes exactly one level
  function _invPushNavLevel(backFn) {
    if (window.innerWidth >= 768) return; // desktop: no drill-down grids, nothing to guard
    history.pushState({ _invNavGuard: true }, '');
    _invNavStack.push(backFn);
  }
  function _invGoBackOneLevel() {
    const backFn = _invNavStack.pop();
    if (backFn) backFn();
  }

  window.addEventListener('popstate', () => {
    if (_modalBackStack.length) { _genericCloseModal(_modalBackStack.pop().el); return; }
    if (_invNavStack.length) { _invGoBackOneLevel(); return; }
    if (_mobileHomeGuardActive) { _mobileHomeGuardActive = false; _mobileTopBarNavClick(); }
  });

  (function () {
    const observer = new MutationObserver(mutations => {
      mutations.forEach(m => {
        if (m.type === 'attributes' && m.attributeName === 'class') {
          const el = m.target;
          if (el.nodeType !== 1 || !_isTrackedModalId(el.id)) return;
          if (_isModalOpen(el)) _onModalOpened(el); else _onModalClosed(el);
        } else if (m.type === 'childList') {
          m.addedNodes.forEach(el => { if (el.nodeType === 1 && _isTrackedModalId(el.id) && _isModalOpen(el)) _onModalOpened(el); });
          m.removedNodes.forEach(el => { if (el.nodeType === 1 && _isTrackedModalId(el.id)) _onModalClosed(el); });
        }
      });
    });
    observer.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
  })();

  // --- NAVIGATION & VIEWS ---

  // Hash routing helpers — give every sidebar view a bookmarkable URL.
  // Uses replaceState so the browser's Back button exits the portal rather
  // than cycling through internal views (desired for a modal-style SPA).
  const _HASH_ROUTES = {
    dashboard:     () => loadDefaultView(),
    system:        () => loadSystemView(),
    committees:    () => loadMyCommittees(),
    messages:      () => loadMessagesView(),
    notifications: () => loadNotificationsView(),
    users:         () => loadUsersDirectory(),
    routine:       () => loadRoutineView(),
    inventory:     () => loadInventoryView(),
    inventory_admin: () => loadInventoryAdminView(),
    my_payslips: () => loadMyPayslipsView(),
    announcements_admin: () => loadAnnouncementsView(),
    myclass:       () => loadMyClassView(),
    lesson_plan:   () => loadLessonPlanView(),
    forum:         () => loadForumView(),
    student_message_history: () => loadStudentMessageHistoryView(),
    textbooks:     () => loadTextbooksView(),
    student_portal:() => loadStudentPortalView(),
    student_portal_menu: () => _openStudentPortalMobileMenu(),
    bus_tracker:   () => loadAdminBusTrackerView(),
    payroll:       () => loadAdminPayrollView(),
    profile:       () => openMyProfile(),
    ssc_result_analysis: () => loadSscResultAnalysisView(),
    home:          () => renderMobileHomeGrid(),
    analytics:     () => loadAnalytics(),
    permissions:   () => loadPermissionsPanel()
  };

  function _setViewHash(key) {
    history.replaceState(null, '', '#' + key);
  }

  function _routeByHash() {
    const key = window.location.hash.slice(1).split('?')[0];
    // Admin-configurable module visibility gates direct hash navigation too,
    // not just the nav links — see MODULE_REGISTRY / _isModuleVisibleForRole.
    // student_portal is exempt from this early gate: a plain Teacher/Staff
    // with only a field-category grant (no role-based visibility at all)
    // must still be able to reach it — loadStudentPortalView does its own
    // complete access check (role OR ERP-tab grant OR field-category
    // grant) and shows the same "not available" toast if none apply.
    if (key && key !== 'student_portal' && MODULE_REGISTRY.some(m => m.key === key) && !_hasModuleAccess(key)) {
      // Silently redirect to dashboard — no error toast for URL tampering
      loadDefaultView();
      return;
    }
    const fn = _HASH_ROUTES[key];
    if (fn) fn(); else loadDefaultView();
  }

  function launchDashboard() {
    if (!window.APP_USER) return;
    const loginScreen = document.getElementById('login-screen');
    if (loginScreen) { loginScreen.classList.add('hidden'); _detachedLoginScreen = loginScreen; loginScreen.remove(); }
    document.getElementById('app-screen').classList.remove('hidden');
    document.getElementById('side-user-role').textContent = window.ACTIVE_ROLE;
    _renderSidebarUserCard();
    updateSidebarForRole(window.ACTIVE_ROLE);
    _loadModuleVisibility(() => { updateSidebarForRole(window.ACTIVE_ROLE); _refreshHomeGridIfVisible(); });
    startSessionHeartbeat();
    loadAndApplyTheme();
    _initRealtime();
    // A fresh mobile login with no saved hash lands on the app-launcher home
    // grid instead of the Administration dashboard — desktop is untouched
    // since this only fires when both conditions hold.
    if (!window.location.hash && window.innerWidth < 768) _setViewHash('home');
    // Route to saved hash (supports refresh & bookmarked views)
    _routeByHash();
    window.addEventListener('hashchange', _routeByHash);
  }

  // Sidebar user card: id/email come straight from the login response for
  // every role; name/shortname/photo need the users_profile row, which
  // loginAndGetProfile only pre-fetches for Teacher/Staff (see
  // window._loginProfile) -- everyone else (Admin, HR, etc.) gets it here
  // via the same self-service getMyProfile lookup the profile-edit view
  // uses, falling back gracefully to just ID+email if that account has no
  // personnel record at all (e.g. an IT-only Admin login).
  // Resets every avatar spot (sidebar card, mobile top bar, profile page
  // photo box) back to its placeholder — called before loading whichever
  // user is now signed in, so a fresh login/role-switch can never show the
  // PREVIOUS session's photo just because setProfilePhoto() only ever
  // overwrites the <img> src and was never called to clear it when the new
  // account happens to have no photo of its own (this was a real bug: one
  // teacher's dashboard was showing a different, previously-logged-in
  // teacher's photo).
  function _clearProfilePhoto() {
    [['photoPreviewImg', 'photoPlaceholder'], ['mobileUserAvatar', 'mobileUserAvatarPh'], ['side-user-photo', 'side-user-photo-ph']].forEach(([imgId, phId]) => {
      const img = document.getElementById(imgId), ph = document.getElementById(phId);
      if (img) { img.removeAttribute('src'); img.classList.add('hidden'); delete img.dataset.fileId; }
      if (ph) ph.classList.remove('hidden');
    });
  }

  function _renderSidebarUserCard() {
    const u = window.APP_USER;
    if (!u) return;
    _clearProfilePhoto();
    const nameEl  = document.getElementById('side-user-name');
    const metaEl  = document.getElementById('side-user-meta');
    const emailEl = document.getElementById('side-user-email');
    if (nameEl)  nameEl.textContent  = u.user_id;
    if (metaEl)  metaEl.textContent  = 'ID: ' + u.user_id;
    if (emailEl) emailEl.textContent = u.email || '—';

    const applyProfile = (p) => {
      if (!p) return;
      if (nameEl && p.full_name) nameEl.textContent = p.full_name + (p.shortname ? ' (' + p.shortname + ')' : '');
      if (metaEl) metaEl.textContent = 'ID: ' + u.user_id;
      if (p.photo_url) setProfilePhoto(p.photo_url);
    };

    if (window._loginProfile) { applyProfile(window._loginProfile); return; }
    google.script.run.withSuccessHandler(applyProfile).withFailureHandler(() => {}).getMyProfile(u.email, u.user_id);
  }

  function _initRealtime() {
    if (!window.APP_USER || !window.supabase) return;
    const myId = window.APP_USER.user_id;
    fetch('/api/config').then(r => r.json()).then(cfg => {
      if (!cfg.supabaseUrl || !cfg.supabaseAnonKey) return;
      _sbClient = window.supabase.createClient(cfg.supabaseUrl, cfg.supabaseAnonKey, {
        realtime: { params: { eventsPerSecond: 10 } }
      });
      _sbChannel = _sbClient.channel('user:' + myId)
        .on('broadcast', { event: 'new_message' }, ({ payload }) => {
          _loadConversations(true);
          refreshMessagesBadge();
          // If the sender's thread is currently open, refresh it immediately
          if (_activePartnerId && payload && payload.from === _activePartnerId) {
            _refreshThread(_activePartnerId, true);
          }
        })
        .on('broadcast', { event: 'typing' }, ({ payload }) => {
          if (payload && payload.from === _activePartnerId) _showTypingIndicator();
        })
        .subscribe();
    }).catch(() => {});
  }

  function _destroyRealtime() {
    try { if (_sbChannel) _sbClient.removeChannel(_sbChannel); } catch(e) {}
    _sbClient  = null;
    _sbChannel = null;
  }

  let _typingTimer    = null;
  let _typingSendTimer = null;
  function _showTypingIndicator() {
    const el = document.getElementById('msgTypingIndicator');
    if (!el) return;
    el.classList.remove('hidden');
    clearTimeout(_typingTimer);
    _typingTimer = setTimeout(() => el.classList.add('hidden'), 3000);
  }
  // Debounced broadcast so we don't flood with every keystroke
  function _broadcastTyping() {
    if (!_sbClient || !_activePartnerId) return;
    if (_typingSendTimer) return;   // already scheduled — skip
    _typingSendTimer = setTimeout(() => {
      _typingSendTimer = null;
      const myId = window.APP_USER && window.APP_USER.user_id;
      if (!myId || !_activePartnerId) return;
      _sbClient.channel('user:' + _activePartnerId)
        .send({ type: 'broadcast', event: 'typing', payload: { from: myId } })
        .catch(() => {});
    }, 1000);
  }

  function updateSidebarForRole(activeRole) {
    const allRoles   = window.USER_ROLES || [activeRole];

    // Per-module visibility — admin-configurable via the System > Module
    // Access panel (MODULE_REGISTRY / _isModuleVisibleForRole). Falls back to
    // the same defaults this used to hardcode until an Admin saves a matrix.
    MODULE_REGISTRY.forEach(m => {
      const el = document.getElementById(m.navId);
      if (el) el.style.display = _hasModuleAccess(m.key) ? '' : 'none';
    });
    // Hide a nav section's group container/label if every link inside it is hidden
    // (nav-sublink items under #erp-links are excluded — they're not gated
    // individually here, and would otherwise read as "visible" via their own
    // unset inline style even while their #erp-links host is hidden below).
    ['admin-links', 'teacher-links'].forEach(id => {
      const container = document.getElementById(id);
      if (!container) return;
      const anyVisible = [...container.querySelectorAll('.nav-link:not(.nav-sublink)')].some(a => a.style.display !== 'none');
      container.classList.toggle('hidden', !anyVisible);
    });

    // #erp-links (the Student Portal accordion's sub-items) is a sibling of
    // #nav-student-portal, not gated by MODULE_REGISTRY itself — it's normally
    // hidden/shown by _loadAdminSubnav's async get_my_tab_access fetch below.
    // On a role switch, hide it immediately/synchronously the moment its
    // parent header goes away, instead of leaving the old role's expanded
    // sub-items visible (with no header above them) until that fetch resolves.
    const spNavEl = document.getElementById('nav-student-portal');
    const erpHost = document.getElementById('erp-links');
    if (spNavEl && erpHost && spNavEl.style.display === 'none') {
      erpHost.classList.add('hidden');
    }

    _maybeRevealStudentPortalForGrantee(activeRole);
    _loadAdminSubnav(activeRole);

    // Profile: read-only list of every role this account holds, doubling as
    // the entry point to that account's own personal-info editor (see
    // openMyProfile — wired via onclick="openMyProfile()" on #role-switcher
    // itself in app.html). Always shown, even for single-role accounts,
    // since Admin's own loadDefaultView branch never lands on the personal
    // info form the way Teacher/Staff's does — this is the only way an
    // Admin-only account reaches its own profile. No role-selection here
    // (the sidebar already exposes every role's modules at once via
    // _hasModuleAccess above); the role list is purely informational,
    // rendered as small static text rather than clickable buttons.
    const switcher = document.getElementById('role-switcher');
    const btnsEl   = document.getElementById('role-switcher-btns');
    if (!switcher) return;
    switcher.classList.remove('hidden');

    if (btnsEl) {
      btnsEl.innerHTML = `<p class="px-1 text-[9px] font-bold tracking-wide" style="color:var(--sidebar-text-hover);">${allRoles.join(', ')}</p>`;
    }
  }

  // A plain Teacher/Staff granted a field-category (student.field_access_grants,
  // via the Admin's "Viewer Access Grants" panel) has no role that makes
  // MODULE_DEFAULTS show the Student Portal nav link — so if the role-based
  // pass just hid it, ask once whether this specific account has any grant
  // anyway, and reveal it if so. Admin/Student Portal Admin already see it
  // via the normal role matrix and never need this extra round-trip.
  function _maybeRevealStudentPortalForGrantee(activeRole) {
    if (activeRole === 'Admin' || activeRole === 'Student Portal Admin') return;
    const myId = window.APP_USER && window.APP_USER.user_id;
    const navEl = document.getElementById('nav-student-portal');
    if (!myId || !navEl || navEl.style.display !== 'none') return;
    Promise.all([
      fetch('/api/student-admin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'get_my_access', payload: {}, user_id: myId })
      }).then(r => r.ok ? r.json() : null).catch(() => null),
      // Tab-data access (Data Access / Class Access / class-teacher-auto /
      // linked Field Category — see getMyTabDataAccess) is a fourth,
      // independent path into Student Portal, on /api/exec rather than
      // /api/student-admin — a grantee with ONLY this (no field-category,
      // no class-wide grant) would otherwise never see the nav link at all.
      new Promise(resolve => {
        google.script.run.withSuccessHandler(resolve).withFailureHandler(() => resolve([])).getMyTabDataAccess(myId);
      }),
    ]).then(([res, tabAccess]) => {
      const hasCategories = res && res.result === 'success' && Array.isArray(res.categories) && res.categories.length;
      const hasClassAccess = res && res.result === 'success' && Array.isArray(res.classAccess) && res.classAccess.length;
      const hasTabData = Array.isArray(tabAccess) && tabAccess.length > 0;
      if (hasCategories || hasClassAccess) window._hasFieldCategoryAccess = true; // loadStudentPortalView's own role gate checks this too
      if (hasTabData) window._hasTabDataAccess = true; // ditto — _studentPortalNavClick/loadStudentPortalView check this
      if (hasCategories || hasClassAccess || hasTabData) {
        navEl.style.display = '';
        const container = document.getElementById('admin-links');
        if (container) container.classList.remove('hidden');
        _refreshHomeGridIfVisible();
      }
    }).catch(() => {});
  }

  // The 12 remaining destinations nested under "Student Portal" in the
  // sidebar (Payroll split out to its own standalone top-level link — see
  // #nav-payroll / loadAdminPayrollView) — every one a native view calling
  // the same /api/student-admin backend directly via _adminFetch (no iframe
  // anywhere in this app anymore). The 4 remaining ERP-tab entries (erp:true)
  // stay gated per-account by the admin-editable admin_tab_visibility matrix
  // (get_my_tab_access, self-service); the rest are shown to any Admin/
  // Student Portal Admin. A plain grantee with neither of those (only a
  // field-category grant) never sees this list at all — see
  // _studentPortalNavClick/loadViewerPanelView.
  const ADMIN_SUBNAV_ITEMS = [
    { key: 'setup', label: 'Setup', icon: 'sliders-horizontal', erp: false, action: { type: 'native', fn: 'loadAdminSetupView' } },
    { key: 'add_custom_form', label: '+ Add Custom Form', icon: 'plus-circle', erp: false, action: { type: 'native', fn: 'loadAdminAddCustomFormView' } },
    { key: 'data', label: 'Data', icon: 'table', erp: false, action: { type: 'native', fn: 'loadAdminDataView' } },
    { key: 'access', label: 'Access', icon: 'shield-check', erp: false, action: { type: 'native', fn: 'loadAdminAccessView' } },
    { key: 'fees', label: 'Fees', icon: 'wallet', erp: true, action: { type: 'native', fn: 'loadAdminFeesView' } },
    { key: 'attendance', label: 'Attendance', icon: 'fingerprint', erp: true, action: { type: 'native', fn: 'loadAdminAttendanceView' } },
    { key: 'exams', label: 'Exams', icon: 'clipboard-list', erp: true, action: { type: 'native', fn: 'loadAdminExamsView' } },
    // 'payroll' deliberately NOT here — it's a standalone top-level sidebar
    // item now (see #nav-payroll / loadAdminPayrollView), same reasoning as
    // bus_tracker's own split out of this list: salary/leave isn't really a
    // "Student Portal" concern, and an HR-only account (Payroll defaults to
    // Admin+HR — see TAB_ACCESS_LABELS/loadAdminAccessView) shouldn't have
    // to open a "Student Portal" accordion to find it. Its account-scoped
    // grant check (get_my_tab_access / window._adminTabAccess) is unchanged
    // — only where the link lives moved, see _loadAdminSubnav below.
    { key: 'transport', label: 'Transport', icon: 'bus', erp: true, action: { type: 'native', fn: 'loadAdminTransportView' } },
    { key: 'history', label: 'History', icon: 'clock', erp: false, action: { type: 'native', fn: 'loadAdminHistoryView' } },
    { key: 'photo', label: 'Photo', icon: 'camera', erp: false, action: { type: 'native', fn: 'loadAdminPhotoView' } },
    { key: 'notices', label: 'Notices', icon: 'megaphone', erp: false, action: { type: 'native', fn: 'loadAdminNoticesView' } },
    { key: 'import', label: 'Import', icon: 'file-spreadsheet', erp: false, action: { type: 'native', fn: 'loadAdminImportView' } },
    // Not admin-tab-visibility-gated like the rest — included whenever
    // getMyTabDataAccess (a completely separate grant system: the global
    // Data Access allowlist, Class Access, class-teacher-auto, or a linked
    // Field Category) returns at least one tab for this account. See
    // _loadAdminSubnav, which merges that check in alongside get_my_tab_access
    // rather than the per-item admin_tab_visibility matrix these other items use.
    { key: 'my_data', label: 'Student Data', icon: 'table', erp: false, action: { type: 'native', fn: 'loadMyTabDataView' } },
    // Forum already exists as a top-level "General" sidebar link, but the
    // Student section of it (targeted posts/messages for a class/student
    // group) is squarely a Student Portal concern — staff kept looking for
    // it inside this accordion and not finding it. Not gated by the ERP
    // admin_tab_visibility matrix like the items above (a plain Teacher
    // browsing Student Portal has no erpTabs at all) — see the
    // 'student_forum' special-case in _loadAdminSubnav's filter below,
    // same pattern as 'my_data'.
    { key: 'student_forum', label: 'Student Forum', icon: 'messages-square', erp: false, action: { type: 'native', fn: 'loadStudentPortalForumView' } },
    { key: 'student_message_history', label: 'Message History', icon: 'message-circle-heart', erp: false, action: { type: 'native', fn: 'loadStudentMessageHistoryView' } },
    { key: 'student_diary', label: 'Diary', icon: 'notebook-tabs', erp: false, action: { type: 'native', fn: 'loadDiaryView' } },
  ];

  function loadStudentPortalForumView() {
    _forumSection = 'student';
    loadForumView();
  }

  // "Student Portal" is a pure expand/collapse subheader now — its own click
  // never navigates anywhere, it just shows/hides the 14 items nested under
  // it in this same sidebar (one panel, not two).
  function toggleAdminSubnav() {
    const host = document.getElementById('erp-links');
    const parent = document.getElementById('nav-student-portal');
    if (!host || !parent) return;
    const nowExpanded = !parent.classList.contains('expanded');
    parent.classList.toggle('expanded', nowExpanded);
    host.classList.toggle('collapsed', !nowExpanded);
  }

  // A field-category-only viewer (see _maybeRevealStudentPortalForGrantee)
  // has no ERP tab and isn't Admin, so _loadAdminSubnav renders zero items
  // under "Student Portal" for them — expanding an empty list would be a
  // dead end. For that one case, clicking the header goes straight to their
  // own restricted Viewer Panel instead of toggling the (empty) subnav.
  function _studentPortalNavClick() {
    const isFullAdmin = window.ACTIVE_ROLE === 'Admin' || window.ACTIVE_ROLE === 'Student Portal Admin';
    if (!isFullAdmin && !window._hasErpTabAccess && window._hasFieldCategoryAccess) {
      loadViewerPanelView();
      return;
    }
    toggleAdminSubnav();
  }

  function _loadAdminSubnav(activeRole) {
    const myId = window.APP_USER && window.APP_USER.user_id;
    const host = document.getElementById('erp-links');
    if (!myId || !host) return;
    Promise.all([
      fetch('/api/student-admin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'get_my_tab_access', payload: {}, user_id: myId })
      }).then(r => r.ok ? r.json() : null).catch(() => null),
      // Student Data ('my_data') is a completely separate grant system
      // (Data Access allowlist / Class Access / class-teacher-auto / linked
      // Field Category — see getMyTabDataAccess) from the admin_tab_visibility
      // matrix get_my_tab_access checks — merged into the same subnav list
      // below rather than routed as a special case, so an account with
      // BOTH kinds of access (e.g. also "+ Add Custom Form") sees both as
      // sibling items instead of only ever reaching one of them.
      new Promise(resolve => {
        google.script.run.withSuccessHandler(resolve).withFailureHandler(() => resolve([])).getMyTabDataAccess(myId);
      }),
    ]).then(([res, tabAccess]) => {
      const erpTabs = (res && res.result === 'success' && Array.isArray(res.tabs)) ? res.tabs : [];
      const hasTabData = Array.isArray(tabAccess) && tabAccess.length > 0;
      // get_my_tab_access now returns every admin-console tab the caller's
      // role clears (not just the original 5 ERP ones) — Admin/Student
      // Portal Admin still get every key via the matrix's own defaults, so
      // this alone decides sidebar visibility for every subnav item.
      window._adminTabAccess = erpTabs;
      window._hasErpTabAccess = erpTabs.length > 0 || hasTabData; // loadStudentPortalView's own role gate checks this too
      // Payroll's nav link visibility is now handled generically by the
      // MODULE_REGISTRY/_hasModuleAccess sidebar loop (payroll_admin key) —
      // no special-casing needed here any more.
      _refreshHomeGridIfVisible();
      // get_my_tab_access is account-scoped (any role the account holds
      // unlocks its tabs) — gated here with the same account-wide
      // _hasModuleAccess used for the "Student Portal" header itself, so
      // the two stay in lockstep (no sub-items surviving under a hidden
      // header, no header shown with an empty accordion). Tab-data access
      // is deliberately exempt from this gate (like the Viewer Panel path
      // already is) since it's its own independent grant, unrelated to
      // which roles the account holds.
      const roleVisibleKeys = _hasModuleAccess('student_portal') ? erpTabs : [];
      // Forum (Student section) and Message History both already exist as
      // top-level "General" sidebar links, but staff kept looking for them
      // inside the Student Portal accordion specifically and not finding
      // them there. Shown here whenever this account has Student Portal
      // access at all (full module access OR tab-data-only grant, same
      // reach as 'my_data' just above) — not restricted to a narrow list of
      // erpTabs like the admin_tab_visibility-gated items above, since a
      // plain Teacher browsing Student Portal typically has none of those.
      const showPortalShortcuts = _hasModuleAccess('student_portal') || hasTabData;
      const items = ADMIN_SUBNAV_ITEMS.filter(i => roleVisibleKeys.includes(i.key) || (i.key === 'my_data' && hasTabData) || (['student_forum', 'student_message_history', 'student_diary'].includes(i.key) && showPortalShortcuts));
      if (!items.length) { host.innerHTML = ''; host.classList.add('hidden'); return; }
      host.innerHTML = items.map(i =>
        `<a href="javascript:void(0)" onclick="${i.action.fn}(); closeMobileSidebar();" class="nav-link nav-sublink" id="nav-erp-${i.key}"><div class="nav-icon-box"><i data-lucide="${i.icon}" class="nav-icon"></i></div><span class="nav-text">${i.label}</span></a>`
      ).join('');
      host.classList.remove('hidden');
      lucide.createIcons();
      const adminLinks = document.getElementById('admin-links');
      if (adminLinks) adminLinks.classList.remove('hidden');
    }).catch(() => {});
  }

  function setActiveNavLink(id) {
    document.querySelectorAll('.nav-link').forEach(el => el.classList.remove('active'));
    const active = document.getElementById(id);
    if (active) active.classList.add('active');
    // Called by literally every module loader with no exceptions — the true
    // universal choke point (more reliable than setContentHeader, which a
    // couple of loaders skip), so this is where the mobile back/home icon
    // gets kept in sync with whatever just navigated.
    _syncMobileTopBarIcon();
    const key = location.hash.slice(1).split('?')[0] || '';
    _trackMobileHomeGuard(key === 'home' || key === '');
  }

  // Mobile top-bar icon button doubles as "open menu" (on the app-launcher
  // home grid) and "back to home" (inside any module) — one dispatcher
  // instead of swapping the onclick attribute itself.
  function _mobileTopBarNavClick() {
    const key = location.hash.slice(1).split('?')[0] || '';
    if (key === 'home' || key === '') openMobileSidebar();
    // Any individual Student Portal sub-view (Setup, Data, Access, …) shares
    // this same hash — back should return to the sub-menu of destinations,
    // not jump all the way past it to Home.
    else if (key === 'student_portal') _openStudentPortalMobileMenu();
    else renderMobileHomeGrid();
  }
  function _syncMobileTopBarIcon() {
    if (window.innerWidth >= 768) return;
    const key = location.hash.slice(1).split('?')[0] || '';
    const iconEl = document.getElementById('mobileTopBarNavIcon');
    if (iconEl) iconEl.setAttribute('data-lucide', (key === 'home' || key === '') ? 'menu' : 'arrow-left');
    if (window.lucide) lucide.createIcons();
  }

  function setContentHeader(title, icon) {
    const t = document.getElementById('content-header-title');
    const i = document.getElementById('content-header-icon');
    const r = document.getElementById('content-header-role');
    if (t) t.textContent = title;
    if (i) { i.setAttribute('data-lucide', icon || 'layout-grid'); lucide.createIcons(); }
    if (r) r.textContent = window.ACTIVE_ROLE || window.USER_ROLE || '';
    const scroller = document.querySelector('main .overflow-y-auto');
    if (scroller) scroller.scrollTop = 0;
  }

  // ── Mobile app-launcher home grid ────────────────────────────────────────
  // Mobile-only landing/navigation layer: a grid of big tiles, one per
  // sidebar link currently visible (derived from the LIVE sidebar DOM, not
  // a second parallel permission list — reuses whatever _hasModuleAccess /
  // _loadAdminSubnav / module-visibility matrix already decided is
  // visible, so it can never drift out of sync with the sidebar itself).
  // Tapping a tile clicks the original sidebar <a>, reusing its exact
  // existing onclick handler — except Student Portal, whose sidebar link
  // only toggles an accordion (no equivalent surface here), so its tile
  // opens a mobile-only sub-menu of its own instead (see
  // _openStudentPortalMobileMenu).
  function renderMobileHomeGrid() {
    if (window.innerWidth >= 768) { loadDefaultView(); return; }
    _setViewHash('home');
    setActiveNavLink();
    setContentHeader('Home', 'layout-grid');
    const container = document.getElementById('view-container');
    if (!container) return;

    // Grouped exactly like the PC sidebar: a single linear scan (in document
    // order — querySelectorAll guarantees this even mixing selectors/depths)
    // over every visible nav-link and every section-label text in the
    // sidebar, bucketing links under whichever label most recently preceded
    // them. This tolerates the sidebar's actual mixed nesting (some groups
    // are wrapper <div>s with their own label+link-list, "General" is a
    // bare label followed by a bare link-list, Dashboard/Routine have no
    // label at all) without hardcoding that structure here — it just
    // mirrors whatever's actually in the DOM, so new groups/labels added to
    // the sidebar later show up here automatically.
    // Profile lives in #role-switcher, a SIBLING of <nav> (not inside it —
    // it's account-level, not a module), so it's prepended by hand into the
    // first (unlabeled) group rather than picked up by the scan below.
    const groups = [];
    let current = { label: null, links: [] };
    const profileLink = document.querySelector('#role-switcher:not(.hidden) .nav-link');
    if (profileLink) current.links.push(profileLink);
    document.querySelectorAll('#main-sidebar nav .nav-link:not(.nav-sublink), #main-sidebar nav .nav-section-label-text').forEach(node => {
      if (node.classList.contains('nav-section-label-text')) {
        if (current.links.length) groups.push(current);
        current = { label: node.textContent, links: [] };
      } else if (node.style.display !== 'none') {
        current.links.push(node);
      }
    });
    if (current.links.length) groups.push(current);

    if (!groups.length) {
      container.innerHTML = `<div class="text-center py-16 text-slate-400 text-xs font-black uppercase tracking-widest">No modules available — contact your administrator</div>`;
      return;
    }

    // Fixed rainbow palette, independent of the active theme — cycling
    // through THEME_PRESETS' own 4-color accent set instead meant tiles
    // stayed tied to (and limited by) whatever theme was active; this way
    // the grid is always maximally colorful and never changes look when a
    // school switches themes. Same 8-color set as the student portal's
    // grid, for visual consistency between the two apps. Cycled across the
    // WHOLE grid (a running index, not reset per group) so colors stay
    // varied instead of every group's first tile always landing on indigo.
    const _homeAccents = ['#6366f1', '#10b981', '#f43f5e', '#f59e0b', '#0ea5e9', '#a855f7', '#14b8a6', '#f97316'];
    let _tileIdx = 0;

    const tileHtml = (el) => {
      const icon = el.querySelector('.nav-icon')?.getAttribute('data-lucide') || 'layout-grid';
      const label = el.querySelector('.nav-text')?.textContent || '';
      const isStudentPortal = el.id === 'nav-student-portal';
      const onclick = el === profileLink ? 'openMyProfile()' : isStudentPortal ? '_openStudentPortalMobileMenu()' : `document.getElementById('${el.id}').click()`;
      const accent = _homeAccents[_tileIdx++ % _homeAccents.length];
      return `
        <button onclick="${onclick}" class="flex flex-col items-center justify-center gap-2.5 p-4 bg-white rounded-3xl shadow-sm hover:shadow-md active:scale-95 transition-all duration-150">
          <div class="w-14 h-14 rounded-2xl flex items-center justify-center" style="background:${_hexToRgba(accent, 0.14)};color:${accent};">
            <i data-lucide="${icon}" class="h-7 w-7"></i>
          </div>
          <span class="text-[10.5px] font-black text-slate-600 text-center leading-tight tracking-tight">${_escHtml(label)}</span>
        </button>`;
    };

    container.innerHTML = groups.map(g => `
      <div class="mb-4">
        ${g.label ? `<p class="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">${_escHtml(g.label)}</p>` : ''}
        <div class="grid grid-cols-3 gap-3">${g.links.map(tileHtml).join('')}</div>
      </div>`).join('')
      // Designer credit — mobile has no always-visible sidebar to anchor it
      // in (off-canvas, hidden by default), so it only shows here, at the
      // bottom of the one mobile-only screen that's roughly this app's
      // "home" — deliberately the smallest text in the UI.
      + `<p class="text-center text-[8px] text-slate-400 font-bold mt-2 mb-1">Designed &amp; Developed by: Md. Mamunur Rashid, CCPC</p>`;
    lucide.createIcons();
  }

  // Re-draws the grid only if it's the currently visible screen — called
  // from every async source that can reveal/hide a sidebar link after the
  // grid's first paint (module-visibility matrix, per-account tab grants,
  // field-category grants), so a tile never silently goes missing just
  // because that fetch hadn't resolved yet when the grid first rendered.
  function _refreshHomeGridIfVisible() {
    if ((location.hash.slice(1).split('?')[0] || '') === 'home') renderMobileHomeGrid();
  }

  // Mobile equivalent of expanding the "Student Portal" sidebar accordion.
  // On PC, tapping the header just reveals the 12 sub-links right there in
  // the sidebar; on mobile there's no equivalent always-visible surface, so
  // the old behavior (jump straight into Setup) left no way back to any of
  // the other 11 destinations. This renders the exact same set of sub-links
  // #erp-links already has (populated by _loadAdminSubnav, so it's always in
  // sync with whatever this account is actually allowed to see) as its own
  // tile grid, one tap away from Home and one tap away from any sub-view via
  // the back arrow (see _mobileTopBarNavClick).
  function _openStudentPortalMobileMenu() {
    if (window.innerWidth >= 768) { loadStudentPortalView(); return; }
    const isFullAdmin = (window.USER_ROLES || [window.ACTIVE_ROLE]).some(r => ['Admin', 'Student Portal Admin'].includes(r));
    if (!isFullAdmin && !window._hasErpTabAccess && window._hasFieldCategoryAccess) {
      // Field-category-only grantee has no sub-menu to show — same shortcut
      // _studentPortalNavClick already uses on PC.
      loadViewerPanelView();
      return;
    }
    const links = Array.from(document.querySelectorAll('#erp-links .nav-link.nav-sublink'));
    if (!links.length) { loadStudentPortalView(); return; } // #erp-links not populated yet — fall back to the old direct-in behavior rather than showing an empty screen

    _setViewHash('student_portal_menu');
    setActiveNavLink('nav-student-portal');
    setContentHeader('Student Portal', 'layout-grid');
    const container = document.getElementById('view-container');
    if (!container) return;
    const accents = ['#6366f1', '#10b981', '#f43f5e', '#f59e0b', '#0ea5e9', '#a855f7', '#14b8a6', '#f97316'];
    container.innerHTML = `<div class="grid grid-cols-3 gap-3">${links.map((el, i) => {
      const icon = el.querySelector('.nav-icon')?.getAttribute('data-lucide') || 'layout-grid';
      const label = el.querySelector('.nav-text')?.textContent || '';
      const accent = accents[i % accents.length];
      return `
        <button onclick="${el.getAttribute('onclick')}" class="flex flex-col items-center justify-center gap-2.5 p-4 bg-white rounded-3xl shadow-sm hover:shadow-md active:scale-95 transition-all duration-150">
          <div class="w-14 h-14 rounded-2xl flex items-center justify-center" style="background:${_hexToRgba(accent, 0.14)};color:${accent};">
            <i data-lucide="${icon}" class="h-7 w-7"></i>
          </div>
          <span class="text-[10.5px] font-black text-slate-600 text-center leading-tight tracking-tight">${_escHtml(label)}</span>
        </button>`;
    }).join('')}</div>`;
    lucide.createIcons();
  }

  function loadDefaultView() {
    _setViewHash('dashboard');
    setActiveNavLink('nav-dashboard');
    const role = window.ACTIVE_ROLE || window.USER_ROLE;
    console.log('[CCPC] loadDefaultView — role:', role);

    if (role === 'Admin') { renderAdminDashboard(); return; }

    showLoading(true);
    const viewMap = { Teacher: 'TeacherView', Staff: 'TeacherView', HR: 'HRView', Principal: 'LeadershipView', VP: 'LeadershipView' };
    const viewFile = (viewMap[role] || 'TeacherView') + '.html';

    fetch('/views/' + viewFile)
      .then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); })
      .then(html => {
        console.log('[CCPC] View HTML loaded, length:', html.length);
        document.getElementById('view-container').innerHTML = html;
        const icons = { Teacher: 'user', Staff: 'user', HR: 'users', Principal: 'crown', VP: 'badge-check' };
        setContentHeader(role + ' Profile', icons[role] || 'user');
        lucide.createIcons();
        if (['Teacher', 'Staff'].includes(role)) {
          const email = window.APP_USER ? window.APP_USER.email   : '';
          const uid   = window.APP_USER ? window.APP_USER.user_id : '';
          const cached = window._loginProfile;
          window._loginProfile = null;
          if (cached) {
            // Profile was pre-loaded during loginAndGetProfile — no second API call needed
            try { renderTeacherProfile(cached); } catch(e) { console.error(e); }
            showLoading(false);
          } else {
            google.script.run
              .withSuccessHandler(data => {
                try { renderTeacherProfile(data); } catch(e) { console.error(e); }
                showLoading(false);
              })
              .withFailureHandler(e => { console.error(e); showLoading(false); })
              .getMyProfile(email, uid);
          }
        } else {
          google.script.run
            .withSuccessHandler(data => {
              try { allStaffCache = Array.isArray(data) ? data : []; renderStaffTable(); renderGradingGrid(); } catch(e) { console.error(e); }
              showLoading(false);
            })
            .withFailureHandler(() => showLoading(false))
            .getAllStaffData(role === 'Principal' || role === 'VP', true);
        }
      })
      .catch(e => { console.error('[CCPC] View load failed:', e); showLoading(false); });
  }

  // Personal-info editor for whichever account is logged in, reachable from
  // the sidebar's "Profile" block regardless of role. loadDefaultView above
  // already lands Teacher/Staff here as their dashboard, but Admin (and any
  // other role) gets a different dashboard there instead — this is the only
  // route back to one's own record for those roles. Reuses TeacherView.html
  // (the same #teacherForm self-profile form) since every account, Admin
  // included, is still a personnel record underneath its role.
  function openMyProfile() {
    _setViewHash('profile');
    setActiveNavLink();
    showLoading(true);
    fetch('/views/TeacherView.html')
      .then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); })
      .then(html => {
        document.getElementById('view-container').innerHTML = html;
        setContentHeader('My Profile', 'user');
        lucide.createIcons();
        const email = window.APP_USER ? window.APP_USER.email   : '';
        const uid   = window.APP_USER ? window.APP_USER.user_id : '';
        google.script.run
          .withSuccessHandler(data => {
            try { renderTeacherProfile(data); } catch (e) { console.error(e); }
            showLoading(false);
          })
          .withFailureHandler(e => { console.error(e); showLoading(false); })
          .getMyProfile(email, uid);
      })
      .catch(e => { console.error('[CCPC] Profile view load failed:', e); showLoading(false); });
  }

  // ── Student Tab Data (delegated access) ──────────────────────────────────
  // Admins pick who may view/export a custom student tab's submissions (Student
  // Portal Admin → Data → Data Access). If this user is on any tab's list,
  // "Student Data" is reachable as its own destination under the Student
  // Portal nav (not auto-injected into their own profile page anymore — see
  // _studentPortalNavClick/loadStudentPortalView for the routing that lands
  // a grantee here, and _maybeRevealStudentPortalForGrantee for what reveals
  // the nav link at all for an account with none of the other Student Portal
  // access paths).
  let _stdTabData = null;
  let _stdTabView = 'table'; // 'table' | 'card'

  function loadMyTabDataView() {
    _setViewHash('student_portal');
    setActiveNavLink('nav-student-portal');
    setContentHeader('Student Data', 'table');
    const container = document.getElementById('view-container');
    if (!container) return;
    const uid = window.APP_USER ? window.APP_USER.user_id : '';
    if (!uid) return;
    container.innerHTML = `<div class="text-center p-10"><i data-lucide="loader-2" class="h-6 w-6 animate-spin inline text-blue-600"></i></div>`;
    lucide.createIcons();
    google.script.run
      .withSuccessHandler(tabs => {
        if (!Array.isArray(tabs) || !tabs.length) {
          container.innerHTML = `<div class="text-center p-10 text-slate-400 font-bold text-sm">No custom tab data has been shared with you.</div>`;
          return;
        }
        container.innerHTML = `
          <div class="max-w-5xl mx-auto bg-white border border-slate-200 rounded-2xl p-5">
            <div class="flex items-center justify-between flex-wrap gap-3 mb-4">
              <div>
                <div class="text-sm font-black text-slate-800">Student Data</div>
                <div class="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Custom tab submissions shared with you</div>
              </div>
              <div class="flex items-center gap-2 flex-wrap">
                <select id="std-tabdata-select" class="border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold text-slate-700"></select>
                <button id="std-tabdata-load" class="px-4 py-1.5 rounded-lg bg-blue-600 text-white text-xs font-black">Load</button>
                <button id="std-tabdata-export" class="px-4 py-1.5 rounded-lg bg-emerald-600 text-white text-xs font-black" disabled>Export CSV</button>
                <select id="std-tabdata-sort" class="border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold text-slate-700">
                  <option value="">Sort: Default</option>
                  <option value="roll">Sort: Roll</option>
                  <option value="student_name">Sort: Name</option>
                  <option value="class">Sort: Class</option>
                  <option value="section">Sort: Section</option>
                  <option value="group">Sort: Group</option>
                  <option value="gender">Sort: Gender</option>
                </select>
                <select id="std-tabdata-filter" class="border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold text-slate-700">
                  <option value="">Show: All</option>
                  <option value="filled">Show: Filled</option>
                  <option value="unfilled">Show: Not Filled</option>
                </select>
                <div class="flex rounded-lg border border-slate-200 overflow-hidden">
                  <button id="std-tabdata-viewtable" class="px-3 py-1.5 text-xs font-black bg-blue-600 text-white">Table</button>
                  <button id="std-tabdata-viewcard" class="px-3 py-1.5 text-xs font-black text-slate-500">Cards</button>
                </div>
                <button id="std-tabdata-merge" class="px-4 py-1.5 rounded-lg border border-slate-200 text-slate-700 text-xs font-black">Merge Columns</button>
                <button id="std-tabdata-print" class="px-4 py-1.5 rounded-lg bg-slate-800 text-white text-xs font-black">Print</button>
              </div>
            </div>
            <div id="std-tabdata-count" class="text-xs font-bold text-slate-500 mb-2"></div>
            <div id="std-tabdata-view" class="border border-slate-100 rounded-xl overflow-x-auto"></div>
          </div>`;
        lucide.createIcons();

        const sel = document.getElementById('std-tabdata-select');
        tabs.forEach(t => {
          const o = document.createElement('option');
          o.value = t.tab_name; o.textContent = t.tab_name;
          sel.appendChild(o);
        });
        document.getElementById('std-tabdata-load').addEventListener('click', () => loadStudentTabData(uid));
        document.getElementById('std-tabdata-export').addEventListener('click', exportStudentTabData);
        document.getElementById('std-tabdata-viewtable').addEventListener('click', () => _setStudentTabView('table'));
        document.getElementById('std-tabdata-viewcard').addEventListener('click', () => _setStudentTabView('card'));
        document.getElementById('std-tabdata-sort').addEventListener('change', (e) => _setStudentTabSort(e.target.value));
        document.getElementById('std-tabdata-filter').addEventListener('change', (e) => _setStudentTabFilter(e.target.value));
        document.getElementById('std-tabdata-merge').addEventListener('click', () => {
          if (!_stdTabData) return;
          _openMergeColumnsModal({
            title: `Merge Columns — ${_stdTabData.tab}`,
            headers: _stdTabData.headers.filter(h => h !== 'student_id'),
            merges: _stdColumnMerges,
            onChange: (m) => { _stdColumnMerges = m; _renderStudentTabData(); },
          });
        });
        document.getElementById('std-tabdata-print').addEventListener('click', () => {
          if (!_stdTabData) return;
          const { headers: dHeaders, rows: dRows } = _applyColumnMerges(_stdTabData.headers, _stdVisibleRows(), _stdColumnMerges);
          _openPrintColumnsModal({
            title: `Print — ${_stdTabData.tab}`,
            headers: dHeaders,
            onPrint: (selected) => {
              const idxs = selected.map(h => dHeaders.indexOf(h));
              const rows = dRows.map(r => idxs.map(i => r[i]));
              _openPrintWindow(_buildPrintHtml(_stdTabData.tab, selected, rows));
            },
          });
        });
      })
      .withFailureHandler(() => {
        container.innerHTML = `<div class="text-center p-10 text-rose-500 font-bold text-sm">Could not load your Student Data access.</div>`;
      })
      .getMyTabDataAccess(uid);
  }

  function _setStudentTabView(mode) {
    _stdTabView = mode;
    const tableBtn = document.getElementById('std-tabdata-viewtable');
    const cardBtn = document.getElementById('std-tabdata-viewcard');
    if (tableBtn) tableBtn.className = `px-3 py-1.5 text-xs font-black ${mode === 'table' ? 'bg-blue-600 text-white' : 'text-slate-500'}`;
    if (cardBtn) cardBtn.className = `px-3 py-1.5 text-xs font-black ${mode === 'card' ? 'bg-blue-600 text-white' : 'text-slate-500'}`;
    _renderStudentTabData();
  }

  let _stdSortKey = ''; // '' | 'roll' | 'student_name' | 'class' | 'section' | 'gender'
  function _setStudentTabSort(key) {
    _stdSortKey = key;
    _renderStudentTabData();
  }

  let _stdFilterKey = ''; // '' | 'filled' | 'unfilled'
  function _setStudentTabFilter(key) {
    _stdFilterKey = key;
    _renderStudentTabData();
  }

  // Display-only column merges for the table view — [{ id, label, cols }].
  // Reset whenever a new tab is loaded (see loadStudentTabData).
  let _stdColumnMerges = [];

  // Shared by render/export so both apply identical sort+filter.
  function _stdVisibleRows() {
    if (!_stdTabData) return [];
    const filled = _stdTabData.filled || {};
    let rows = _stdTabData.rows;
    if (_stdSortKey && _stdTabData.sortMeta) {
      const meta = _stdTabData.sortMeta;
      rows = [...rows].sort((a, b) => _sortCompare((meta[a[0]] || {})[_stdSortKey], (meta[b[0]] || {})[_stdSortKey]));
    }
    if (_stdFilterKey === 'filled') rows = rows.filter(r => filled[r[0]]);
    else if (_stdFilterKey === 'unfilled') rows = rows.filter(r => !filled[r[0]]);
    return rows;
  }

  // Generic numeric-aware comparator, matching the convention already used
  // for roll-number sorting elsewhere (My Class roster, etc.).
  function _sortCompare(va, vb) {
    const na = Number(va), nb = Number(vb);
    if (va !== undefined && vb !== undefined && va !== '' && vb !== '' && va != null && vb != null && !isNaN(na) && !isNaN(nb)) return na - nb;
    return String(va ?? '').localeCompare(String(vb ?? ''), undefined, { numeric: true });
  }

  function _prettyHeader(h) {
    return String(h || '').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  }

  function _statusBadge(isFilled) {
    return isFilled
      ? '<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Filled</span>'
      : '<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-slate-100 text-slate-500 text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Not Filled</span>';
  }

  // ── Colorful tab-data tables: shared by the Student Data card and My Class
  // tab-table (both live in this file). Cycles by column index, deliberately
  // excluding green/red/emerald — those stay reserved for the Filled/Not
  // Filled status badge above.
  const _COL_PALETTE = [
    { head: 'bg-blue-100 text-blue-700', cell: 'bg-blue-50/60', hex: '#dbeafe', hexCell: '#eff6ff' },
    { head: 'bg-indigo-100 text-indigo-700', cell: 'bg-indigo-50/60', hex: '#e0e7ff', hexCell: '#eef2ff' },
    { head: 'bg-violet-100 text-violet-700', cell: 'bg-violet-50/60', hex: '#ede9fe', hexCell: '#f5f3ff' },
    { head: 'bg-fuchsia-100 text-fuchsia-700', cell: 'bg-fuchsia-50/60', hex: '#fae8ff', hexCell: '#fdf4ff' },
    { head: 'bg-amber-100 text-amber-700', cell: 'bg-amber-50/60', hex: '#fef3c7', hexCell: '#fffbeb' },
    { head: 'bg-cyan-100 text-cyan-700', cell: 'bg-cyan-50/60', hex: '#cffafe', hexCell: '#ecfeff' },
    { head: 'bg-teal-100 text-teal-700', cell: 'bg-teal-50/60', hex: '#ccfbf1', hexCell: '#f0fdfa' },
    { head: 'bg-orange-100 text-orange-700', cell: 'bg-orange-50/60', hex: '#fed7aa', hexCell: '#fff7ed' },
  ];
  function _colTint(i) { return _COL_PALETTE[i % _COL_PALETTE.length]; }

  // Display-only column merge: collapses configured column groups into one
  // cell each, at the leftmost merged column's position. Never touches
  // sort/filter/export — callers apply this only when building table markup,
  // strictly after sort+filter have already run on the original headers/rows.
  function _applyColumnMerges(headers, rows, merges) {
    if (!merges || !merges.length) return { headers, rows };
    const groups = merges
      .map(m => ({ ...m, idxs: m.cols.map(c => headers.indexOf(c)).filter(i => i >= 0) }))
      .filter(g => g.idxs.length >= 2);
    if (!groups.length) return { headers, rows };
    const anchorOf = {};
    const dropSet = new Set();
    groups.forEach(g => {
      const anchor = Math.min(...g.idxs);
      anchorOf[anchor] = g;
      g.idxs.forEach(i => { if (i !== anchor) dropSet.add(i); });
    });
    const dHeaders = [];
    const colPlan = [];
    headers.forEach((h, i) => {
      if (dropSet.has(i)) return;
      if (anchorOf[i]) { dHeaders.push(anchorOf[i].label); colPlan.push({ merge: anchorOf[i].idxs }); return; }
      dHeaders.push(h);
      colPlan.push({ idx: i });
    });
    const dRows = rows.map(r => colPlan.map(p => p.merge
      ? p.merge.map(i => r[i]).filter(v => v !== '' && v != null).join('<br>')
      : r[p.idx]));
    return { headers: dHeaders, rows: dRows };
  }

  // ── Merge Columns modal — generic, reused by both surfaces in this file.
  // opts: { title, headers (candidates to offer), merges (current array),
  //         onChange(newMergesArray) }
  let _activeMergeModalOpts = null;
  function _openMergeColumnsModal(opts) {
    _activeMergeModalOpts = opts;
    const existing = document.getElementById('merge-columns-overlay');
    if (existing) existing.remove();
    const usedCols = new Set(opts.merges.flatMap(m => m.cols));
    const available = opts.headers.filter(h => !usedCols.has(h));
    const overlay = document.createElement('div');
    overlay.id = 'merge-columns-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:3000;display:flex;align-items:center;justify-content:center;padding:16px';
    overlay.innerHTML = `
      <div style="background:#fff;border-radius:16px;max-width:520px;width:100%;max-height:85vh;display:flex;flex-direction:column">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;border-bottom:1px solid #e2e8f0">
          <strong>${opts.title || 'Merge Columns'}</strong>
          <button onclick="document.getElementById('merge-columns-overlay').remove()" style="border:none;background:none;font-size:18px;cursor:pointer;line-height:1">&times;</button>
        </div>
        <div id="merge-columns-chips" style="padding:${opts.merges.length ? '12px 16px 0' : '0'};display:flex;flex-wrap:wrap;gap:6px"></div>
        <div style="overflow-y:auto;flex:1;padding:12px 16px">
          <input type="text" id="merge-columns-label" placeholder="Label for the merged column (optional)" style="width:100%;padding:6px 10px;border:1px solid #cbd5e1;border-radius:8px;margin-bottom:10px;font-size:13px;box-sizing:border-box">
          <div id="merge-columns-picker" style="display:flex;flex-direction:column;gap:4px;max-height:280px;overflow-y:auto">
            ${available.length ? available.map(h => `<label style="display:flex;align-items:center;gap:6px;font-size:13px;cursor:pointer"><input type="checkbox" class="merge-col-check" value="${String(h).replace(/"/g, '&quot;')}">${h}</label>`).join('') : '<span style="font-size:12px;color:#94a3b8">No more columns available to merge.</span>'}
          </div>
        </div>
        <div style="padding:12px 16px;border-top:1px solid #e2e8f0;display:flex;justify-content:flex-end">
          <button id="merge-columns-create" style="background:#2563eb;color:#fff;border:none;border-radius:8px;padding:7px 16px;font-weight:800;font-size:13px;cursor:pointer">Create Merge</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);

    const chipsHost = document.getElementById('merge-columns-chips');
    chipsHost.innerHTML = opts.merges.map(m => `<span style="display:inline-flex;align-items:center;gap:5px;background:#eff6ff;color:#1d4ed8;border-radius:999px;padding:4px 10px;font-size:12px;font-weight:700">
        ${m.label} &middot; ${m.cols.length} cols
        <span data-id="${m.id}" style="cursor:pointer;font-weight:900" onclick="_removeColumnMerge('${m.id}')">&times;</span>
      </span>`).join('');

    document.getElementById('merge-columns-create').addEventListener('click', () => {
      const label = document.getElementById('merge-columns-label').value.trim();
      const cols = Array.from(document.querySelectorAll('.merge-col-check:checked')).map(c => c.value);
      if (cols.length < 2) { if (typeof showToast === 'function') showToast('Pick at least 2 columns to merge', 'error'); return; }
      const finalLabel = label || cols.map(_prettyHeader).join(' / ');
      const newMerges = [...opts.merges, { id: 'm' + Date.now() + Math.random().toString(36).slice(2, 6), label: finalLabel, cols }];
      opts.onChange(newMerges);
      opts.merges = newMerges;
      _openMergeColumnsModal(opts);
    });
  }
  function _removeColumnMerge(id) {
    if (!_activeMergeModalOpts) return;
    const newMerges = _activeMergeModalOpts.merges.filter(m => m.id !== id);
    _activeMergeModalOpts.onChange(newMerges);
    _activeMergeModalOpts.merges = newMerges;
    _openMergeColumnsModal(_activeMergeModalOpts);
  }

  // ── Print column-picker modal — generic, reused by both surfaces here.
  // opts: { title, headers (already post-merge display headers), onPrint(selectedHeaders) }
  function _openPrintColumnsModal(opts) {
    const existing = document.getElementById('print-columns-overlay');
    if (existing) existing.remove();
    const overlay = document.createElement('div');
    overlay.id = 'print-columns-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:3000;display:flex;align-items:center;justify-content:center;padding:16px';
    overlay.innerHTML = `
      <div style="background:#fff;border-radius:16px;max-width:420px;width:100%;max-height:85vh;display:flex;flex-direction:column">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;border-bottom:1px solid #e2e8f0">
          <strong>${opts.title || 'Print'}</strong>
          <button onclick="document.getElementById('print-columns-overlay').remove()" style="border:none;background:none;font-size:18px;cursor:pointer;line-height:1">&times;</button>
        </div>
        <div style="padding:10px 16px 0;display:flex;gap:8px">
          <button id="print-columns-all" style="font-size:11px;border:1px solid #cbd5e1;border-radius:999px;padding:3px 10px;background:#fff;cursor:pointer">Select all</button>
          <button id="print-columns-none" style="font-size:11px;border:1px solid #cbd5e1;border-radius:999px;padding:3px 10px;background:#fff;cursor:pointer">Clear</button>
        </div>
        <div id="print-columns-list" style="overflow-y:auto;flex:1;padding:10px 16px 12px;display:flex;flex-direction:column;gap:4px">
          ${opts.headers.map(h => `<label style="display:flex;align-items:center;gap:6px;font-size:13px;cursor:pointer"><input type="checkbox" class="print-col-check" value="${String(h).replace(/"/g, '&quot;')}" checked>${h}</label>`).join('')}
        </div>
        <div style="padding:12px 16px;border-top:1px solid #e2e8f0;display:flex;justify-content:flex-end">
          <button id="print-columns-go" style="background:#2563eb;color:#fff;border:none;border-radius:8px;padding:7px 16px;font-weight:800;font-size:13px;cursor:pointer">Print</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    document.getElementById('print-columns-all').addEventListener('click', () => { document.querySelectorAll('.print-col-check').forEach(c => { c.checked = true; }); });
    document.getElementById('print-columns-none').addEventListener('click', () => { document.querySelectorAll('.print-col-check').forEach(c => { c.checked = false; }); });
    document.getElementById('print-columns-go').addEventListener('click', () => {
      const selected = Array.from(document.querySelectorAll('.print-col-check:checked')).map(c => c.value);
      if (!selected.length) { if (typeof showToast === 'function') showToast('Pick at least one column', 'error'); return; }
      document.getElementById('print-columns-overlay').remove();
      opts.onPrint(selected);
    });
  }

  // Standalone printable HTML document — no Tailwind CDN in the popup window,
  // so tints are inlined as literal colors via _colTint(...).hex/hexCell.
  function _buildPrintHtml(title, headers, rows) {
    const theadCells = headers.map((h, i) => `<th style="background:${_colTint(i).hex};color:#1e293b;border:1px solid #cbd5e1;padding:5px 7px;font-size:9pt;text-transform:uppercase;letter-spacing:.04em;text-align:left">${h}</th>`).join('');
    const bodyRows = rows.map(r => `<tr>${r.map((c, i) => `<td style="background:${_colTint(i).hexCell};border:1px solid #cbd5e1;padding:4px 7px;font-size:9pt">${c === '' || c == null ? '&mdash;' : c}</td>`).join('')}</tr>`).join('');
    return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>${title}</title>
      <style>
        @page { size: landscape; margin: 10mm; }
        body { font-family: -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; margin: 0; padding: 16px; }
        table { border-collapse: collapse; width: 100%; }
        .print-meta { font-size: 8pt; color: #64748b; margin-bottom: 10px; }
        h1 { font-size: 13pt; margin: 0 0 2px; }
      </style></head>
      <body>
        <h1>${title}</h1>
        <div class="print-meta">Printed ${new Date().toLocaleString()} &mdash; ${rows.length} row${rows.length === 1 ? '' : 's'}</div>
        <table><thead><tr>${theadCells}</tr></thead><tbody>${bodyRows}</tbody></table>
      </body></html>`;
  }

  function _openPrintWindow(html) {
    const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const win = window.open(url, '_blank', 'width=1100,height=750');
    if (!win) {
      if (typeof showToast === 'function') showToast('Popup blocked — please allow popups for this site and try again', 'error');
      URL.revokeObjectURL(url);
      return;
    }
    win.focus();
    setTimeout(function () { win.print(); setTimeout(function () { URL.revokeObjectURL(url); }, 1000); }, 800);
  }

  function _renderStudentTabData() {
    const view = document.getElementById('std-tabdata-view');
    if (!view) return;
    if (!_stdTabData) { view.innerHTML = ''; return; }
    const { headers } = _stdTabData;
    const filled = _stdTabData.filled || {};
    const rows = _stdVisibleRows();
    if (!rows.length) {
      view.innerHTML = `<div class="p-4 text-xs font-bold text-slate-400">${_stdFilterKey ? 'No students match this filter.' : 'No students found.'}</div>`;
      return;
    }
    if (_stdTabView === 'table') {
      const { headers: dHeaders, rows: dRows } = _applyColumnMerges(headers, rows, _stdColumnMerges);
      view.innerHTML = `<table class="w-full text-left">
        <thead class="bg-slate-50"><tr><th class="px-3 py-2 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">Status</th>${dHeaders.map((h, i) => `<th class="px-3 py-2 text-[10px] font-black uppercase tracking-widest whitespace-nowrap ${_colTint(i).head}">${_escHtml(h)}</th>`).join('')}</tr></thead>
        <tbody>${dRows.map((r, ri) => `<tr class="border-t border-slate-100"><td class="px-3 py-2">${_statusBadge(filled[rows[ri][0]])}</td>${r.map((c, i) => `<td class="px-3 py-2 text-xs font-semibold text-slate-700 ${_colTint(i).cell}">${c === '' || c == null ? '—' : _escHtml(c)}</td>`).join('')}</tr>`).join('')}</tbody>
      </table>`;
      return;
    }
    // Card view: one card per student, identity fields as the header, then
    // only the fields that student actually filled in. Label stacks above
    // value (not side-by-side) — real forms have long labels and long
    // values that overflowed past the card edge in the old layout.
    const idIdx = headers.indexOf('student_id');
    const nameIdx = headers.indexOf('student_name');
    const clsIdx = headers.indexOf('class');
    const secIdx = headers.indexOf('section');
    const rollIdx = headers.indexOf('roll');
    const identityIdx = new Set([idIdx, nameIdx, clsIdx, secIdx, rollIdx].filter(i => i >= 0));
    view.innerHTML = `<div class="grid grid-cols-1 sm:grid-cols-2 gap-3 p-3 bg-slate-50">
      ${rows.map(r => {
        const title = _escHtml((nameIdx >= 0 && r[nameIdx]) || (idIdx >= 0 && r[idIdx]) || 'Student');
        const sub = _escHtml([
          idIdx >= 0 ? r[idIdx] : null,
          (clsIdx >= 0 && r[clsIdx]) ? `${r[clsIdx]}${(secIdx >= 0 && r[secIdx]) ? '-' + r[secIdx] : ''}` : null,
          (rollIdx >= 0 && r[rollIdx]) ? `Roll ${r[rollIdx]}` : null,
        ].filter(Boolean).join(' · '));
        const fields = headers
          .map((h, i) => ({ h, v: r[i], i }))
          .filter(f => !identityIdx.has(f.i) && f.v !== '' && f.v != null);
        return `<div class="bg-white border border-slate-200 rounded-xl p-4">
          <div class="flex items-start justify-between gap-2">
            <p class="text-sm font-black text-slate-800">${title}</p>
            ${_statusBadge(filled[r[0]])}
          </div>
          <p class="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">${sub}</p>
          ${fields.length ? `<div class="pt-2 border-t border-slate-50 flex flex-col gap-2.5">
            ${fields.map(f => `<div>
              <p class="text-[9.5px] font-bold text-slate-400 uppercase tracking-wide leading-tight">${_escHtml(_prettyHeader(f.h))}</p>
              <p class="text-xs font-semibold text-slate-700 mt-0.5 break-words">${_escHtml(String(f.v))}</p>
            </div>`).join('')}
          </div>` : '<p class="text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2 border-t border-slate-50">No data filled in</p>'}
        </div>`;
      }).join('')}
    </div>`;
  }

  function loadStudentTabData(uid) {
    const sel = document.getElementById('std-tabdata-select');
    const view = document.getElementById('std-tabdata-view');
    const count = document.getElementById('std-tabdata-count');
    const exportBtn = document.getElementById('std-tabdata-export');
    const sortSel = document.getElementById('std-tabdata-sort');
    const filterSel = document.getElementById('std-tabdata-filter');
    if (!sel || !sel.value) return;
    view.innerHTML = '<div class="p-4 text-xs font-bold text-slate-400">Loading…</div>';
    google.script.run
      .withSuccessHandler(res => {
        if (!res || res.error) {
          view.innerHTML = `<div class="p-4 text-xs font-bold text-rose-500">${(res && res.error) || 'Could not load data.'}</div>`;
          exportBtn.disabled = true;
          return;
        }
        _stdSortKey = '';
        _stdFilterKey = '';
        _stdColumnMerges = [];
        if (sortSel) sortSel.value = '';
        if (filterSel) filterSel.value = '';
        _stdTabData = { tab: sel.value, headers: res.headers, rows: res.rows, sortMeta: res.sort_meta || {}, filled: res.filled || {} };
        _renderStudentTabData();
        const filledCount = res.rows.filter(r => (res.filled || {})[r[0]]).length;
        count.textContent = `${filledCount} of ${res.rows.length} student${res.rows.length === 1 ? '' : 's'} filled "${sel.value}" — ${res.rows.length - filledCount} not filled`;
        exportBtn.disabled = res.rows.length === 0;
      })
      .withFailureHandler(e => {
        view.innerHTML = `<div class="p-4 text-xs font-bold text-rose-500">${e && e.message ? e.message : e}</div>`;
        exportBtn.disabled = true;
      })
      .getTabDataForUser(uid, sel.value);
  }

  function exportStudentTabData() {
    if (!_stdTabData || !_stdTabData.rows.length) return;
    // Export whatever sort/filter is currently on screen.
    const rows = _stdVisibleRows();
    const filled = _stdTabData.filled || {};
    const esc = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
    const csv = ['Status', ..._stdTabData.headers].map(esc).join(',') + '\n'
      + rows.map(r => [filled[r[0]] ? 'Filled' : 'Not Filled', ...r].map(esc).join(',')).join('\n');
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8' }));
    a.download = `${_stdTabData.tab}_export.csv`;
    a.click();
  }

