  // ═══════════════════════════════════════════════════════
  //  NOTIFICATIONS
  // ═══════════════════════════════════════════════════════

  function refreshNotifBadge() {
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run.withSuccessHandler(notifs => {
      const unread = Array.isArray(notifs) ? notifs.filter(n => !n.is_read).length : 0;
      const badge = document.getElementById('notifBadge');
      if (!badge) return;
      if (unread > 0) {
        badge.textContent = unread > 99 ? '99+' : unread;
        badge.classList.remove('hidden');
      } else {
        badge.classList.add('hidden');
      }
    }).withFailureHandler(() => {}).getMyNotifications(myId);
  }

  function openNotificationsPanel() {
    loadNotificationsView();
  }

  // Routes by the SHAPE of n.data rather than an exact n.type string match —
  // any notification carrying a post_id goes to that forum post/reply
  // (forum_post/forum_mention/forum_reply all carry the same shape), any
  // carrying a committee_id opens that committee's chat (mention/
  // committee_closed), class_adjusted has no id to deep-link to so it just
  // opens Routine. This is deliberately loose so a notification type added
  // later works automatically as long as its data uses these same field
  // names, instead of needing every type spelled out in a lookup table.
  function _notifRoute(n) {
    const d = (n && n.data) || {};
    if (d.post_id) return () => _forumOpenPostFromNotification(d.post_id);
    if (d.committee_id) return () => openCommChat(d.committee_id, d.committee_name);
    if (n && n.type === 'class_adjusted') return () => loadRoutineView();
    return null;
  }
  // Every notification is clickable (marks itself read), and additionally
  // navigates when _notifRoute finds somewhere relevant to go.
  function _notifNavigate(n) {
    if (!n.is_read) google.script.run.withSuccessHandler(() => refreshNotifBadge()).withFailureHandler(() => {}).markNotificationRead(n.id);
    const route = _notifRoute(n);
    if (route) route();
  }

  function loadNotificationsView() {
    _setViewHash('notifications');
    setActiveNavLink('nav-notifications');
    const container = document.getElementById('view-container');
    if (!container) return;
    document.getElementById('content-header-title').textContent = 'Notifications';
    const icon = document.getElementById('content-header-icon');
    if (icon) icon.setAttribute('data-lucide','bell');
    lucide.createIcons();

    container.innerHTML = `
      <div class="pt-6 space-y-4">
        <div class="flex items-center justify-between mb-4">
          <p class="font-black text-slate-800 text-sm uppercase tracking-widest">Your Notifications</p>
          <button onclick="markAllNotificationsRead()" class="flex items-center gap-1.5 px-4 py-2 bg-blue-50 hover:bg-blue-600 hover:text-white text-blue-600 text-[10px] font-black rounded-xl transition-all uppercase tracking-widest">
            <i data-lucide="check-check" class="h-3 w-3"></i> Mark All Read
          </button>
        </div>
        <div id="notifList" class="space-y-2">
          <div class="text-center py-8 text-slate-400 text-xs font-black uppercase tracking-widest">Loading notifications…</div>
        </div>
      </div>`;
    lucide.createIcons();

    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run.withSuccessHandler(notifs => {
      const list = document.getElementById('notifList');
      if (!list) return;
      if (!Array.isArray(notifs) || !notifs.length) {
        list.innerHTML = `<div class="text-center py-12 text-slate-300 text-xs font-black uppercase tracking-widest">No notifications yet</div>`;
        return;
      }
      list.innerHTML = notifs.map(n => {
        const isUnread = !n.is_read;
        const timeStr = n.created_at ? new Date(n.created_at).toLocaleString('en-BD',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}) : '—';
        const hasRoute = !!_notifRoute(n);
        return `<div onclick="_notifNavigate(${_escHtml(JSON.stringify(n))})" class="cursor-pointer active:scale-[0.99] flex items-start gap-4 p-4 rounded-2xl border transition-all ${isUnread ? 'bg-blue-50 border-blue-200 border-l-4' : 'bg-white border-slate-100 hover:bg-slate-50'}">
          <div class="w-8 h-8 rounded-xl flex items-center justify-center shrink-0 ${isUnread ? 'bg-blue-100' : 'bg-slate-100'}">
            <i data-lucide="bell" class="h-3.5 w-3.5 ${isUnread ? 'text-blue-600' : 'text-slate-400'}"></i>
          </div>
          <div class="flex-1 min-w-0">
            <p class="font-black text-slate-800 text-sm">${n.title||'Notification'}</p>
            <p class="text-xs text-slate-500 font-bold mt-0.5">${n.message||''}</p>
            <p class="text-[10px] text-slate-400 mt-1">${timeStr}${hasRoute ? ' · Tap to open' : ''}</p>
          </div>
          <div class="flex flex-col items-end gap-2 shrink-0">
            <span class="px-2 py-0.5 text-[9px] font-black uppercase rounded-full ${isUnread ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}">${isUnread ? 'Unread' : 'Read'}</span>
            ${isUnread ? `<button onclick="event.stopPropagation(); markNotifRead('${n.id}')" class="text-[9px] font-black text-blue-500 hover:text-blue-700 uppercase tracking-widest">Mark Read</button>` : ''}
          </div>
        </div>`;
      }).join('');
      lucide.createIcons();
    }).withFailureHandler(() => {
      const list = document.getElementById('notifList');
      if (list) list.innerHTML = `<div class="text-center py-8 text-red-400 text-xs font-black uppercase">Failed to load notifications</div>`;
    }).getMyNotifications(myId);
  }

  function markNotifRead(id) {
    google.script.run.withSuccessHandler(() => {
      loadNotificationsView();
      refreshNotifBadge();
    }).withFailureHandler(() => showToast('Failed to mark read', 'error')).markNotificationRead(id);
  }

  function markAllNotificationsRead() {
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run.withSuccessHandler(() => {
      showToast('All notifications marked as read');
      loadNotificationsView();
      refreshNotifBadge();
    }).withFailureHandler(() => showToast('Failed', 'error')).markAllNotificationsRead(myId);
  }

  // ═══════════════════════════════════════════════════════
  //  USERS DIRECTORY
  // ═══════════════════════════════════════════════════════

  let _allUsersCache = [];

  function _presenceInfo(lastActiveStr) {
    if (!lastActiveStr) return { cls: 'bg-slate-300', label: 'Never active' };
    const diffMin = Math.floor((Date.now() - new Date(lastActiveStr).getTime()) / 60000);
    if (diffMin < 5)  return { cls: 'bg-emerald-400', label: 'Active now' };
    if (diffMin < 60) return { cls: 'bg-amber-400',   label: diffMin + 'm ago' };
    const diffHr = Math.floor(diffMin / 60);
    return { cls: 'bg-slate-300', label: diffHr < 24 ? diffHr + 'h ago' : Math.floor(diffHr/24) + 'd ago' };
  }

  function _renderUserCards(users) {
    const grid = document.getElementById('usersGrid');
    if (!grid) return;
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!users.length) {
      grid.innerHTML = `<div class="col-span-3 text-center py-12 text-slate-300 text-xs font-black uppercase">No users found</div>`;
      return;
    }
    grid.innerHTML = users.map(u => {
      const { cls, label } = _presenceInfo(u.last_active);
      const roles = (u.role||'').split(',').map(r=>r.trim()).filter(Boolean);
      const roleChips = roles.map(r => `<span class="px-2 py-0.5 bg-indigo-100 text-indigo-700 text-[9px] font-black rounded-full uppercase">${r}</span>`).join('');
      const photoSrc = u.photo_url ? (u.photo_url.startsWith('http') ? u.photo_url : 'https://lh3.googleusercontent.com/d/' + u.photo_url) : '';
      const avatarHtml = photoSrc
        ? `<img src="${photoSrc}" class="w-full h-full object-cover absolute inset-0" onerror="this.style.display='none'">`
        : `<i data-lucide="user" class="h-5 w-5 text-white"></i>`;
      const isSelf = u.user_id === myId;
      const rawNum = (u.whatsapp || u.phone || '').trim();
      const waNum  = rawNum.replace(/\D/g, '');   // digits only for wa.me URL
      const telNum = rawNum.replace(/[\s\-()]/g, ''); // keep + for tel:
      return `<div onclick="openColleagueProfile('${u.user_id}')" class="bg-white rounded-2xl p-4 border border-slate-200 shadow-sm hover:shadow-md transition-all flex flex-col gap-3 cursor-pointer">
        <div class="flex items-center gap-3">
          <div class="relative shrink-0">
            <div class="w-12 h-12 rounded-xl overflow-hidden relative bg-gradient-to-tr from-blue-600 to-indigo-500 flex items-center justify-center">
              ${avatarHtml}
            </div>
            <span class="absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-white ${cls}"></span>
          </div>
          <div class="flex-1 min-w-0">
            <p class="font-black text-slate-800 text-sm truncate">${u.full_name || u.user_id || '—'}</p>
            ${u.designation ? `<p class="text-[10px] text-blue-600 font-black uppercase tracking-wide truncate">${u.designation}</p>` : ''}
            ${rawNum ? `<div class="flex items-center gap-1.5 mt-0.5">
              <span class="text-[9px] text-slate-400 font-bold select-all">${rawNum}</span>
              <a href="tel:${telNum}" onclick="event.stopPropagation()" title="Call" class="text-slate-300 hover:text-blue-600 transition-colors"><i data-lucide="phone" class="h-3 w-3"></i></a>
              <a href="https://wa.me/${waNum}" target="_blank" onclick="event.stopPropagation()" title="WhatsApp" class="text-slate-300 hover:text-emerald-500 transition-colors"><i data-lucide="message-circle" class="h-3 w-3"></i></a>
            </div>` : ''}
          </div>
        </div>
        <div class="flex flex-wrap gap-1">${roleChips || '<span class="text-[9px] text-slate-300 font-bold">No role</span>'}</div>
        <div class="flex items-center justify-between pt-1 border-t border-slate-100">
          <span class="text-[9px] text-slate-400 font-bold">${label}</span>
          ${!isSelf ? `<button onclick="event.stopPropagation(); openDirectMessage('${u.user_id}','${(u.full_name||u.user_id).replace(/'/g,"\\'")}','${photoSrc.replace(/'/g,"\\'")}')"
            class="flex items-center gap-1.5 px-3 py-1.5 bg-blue-50 hover:bg-blue-600 hover:text-white text-blue-600 text-[9px] font-black rounded-xl transition-all uppercase tracking-widest">
            <i data-lucide="send" class="h-3 w-3"></i> Message
          </button>` : `<span class="text-[9px] text-emerald-600 font-black uppercase">You</span>`}
        </div>
      </div>`;
    }).join('');
    lucide.createIcons();
  }

  function loadUsersDirectory() {
    _setViewHash('users');
    setActiveNavLink('nav-users-directory');
    const container = document.getElementById('view-container');
    if (!container) return;
    document.getElementById('content-header-title').textContent = 'Users Directory';
    const icon = document.getElementById('content-header-icon');
    if (icon) icon.setAttribute('data-lucide','users');
    lucide.createIcons();

    container.innerHTML = `
      <div class="pt-4 flex flex-col gap-4">
        <div class="flex items-center gap-3">
          <div class="relative flex-1 max-w-sm">
            <i data-lucide="search" class="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-400 pointer-events-none"></i>
            <input id="userDirSearch" type="search" placeholder="Search by name, role, designation…"
              autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" name="ccpc-userdir-search"
              oninput="filterUserDirectory(this.value)"
              class="w-full pl-9 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-600 transition-all">
          </div>
          <span id="userDirCount" class="text-[10px] font-black text-slate-400 uppercase tracking-widest shrink-0"></span>
        </div>
        <div id="usersGrid" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          <div class="col-span-3 text-center py-12 text-slate-400 text-xs font-black uppercase tracking-widest">Loading users…</div>
        </div>
      </div>

      <div id="colleagueProfileModal" class="modal-wrap hidden fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
        <div class="modal-box relative bg-white rounded-3xl w-full max-w-2xl shadow-2xl overflow-hidden" style="max-height:92vh;display:flex;flex-direction:column">
          <button onclick="closeColleagueProfileModal()" class="absolute top-4 right-4 z-10 w-8 h-8 rounded-full bg-black/20 hover:bg-black/35 text-white flex items-center justify-center transition-all backdrop-blur-sm"><i data-lucide="x" class="h-4 w-4"></i></button>
          <div id="colleagueProfileBody" class="overflow-y-auto bg-slate-50" style="flex:1">
            <div class="text-center py-16"><i data-lucide="loader-2" class="h-6 w-6 animate-spin inline text-blue-600"></i></div>
          </div>
        </div>
      </div>`;
    lucide.createIcons();

    google.script.run
      .withSuccessHandler(users => {
        _allUsersCache = Array.isArray(users) ? users : [];
        const count = document.getElementById('userDirCount');
        if (count) count.textContent = _allUsersCache.length + ' users';
        _renderUserCards(_allUsersCache);
      })
      .withFailureHandler(() => {
        const grid = document.getElementById('usersGrid');
        if (grid) grid.innerHTML = `<div class="col-span-3 text-center py-8 text-red-400 text-xs font-black uppercase">Failed to load users</div>`;
      })
      .getAllUsersWithPresence();
  }

  function filterUserDirectory(q) {
    const term = (q||'').toLowerCase().trim();
    const count = document.getElementById('userDirCount');
    if (!term) {
      if (count) count.textContent = _allUsersCache.length + ' users';
      _renderUserCards(_allUsersCache);
      return;
    }
    const filtered = _allUsersCache.filter(u =>
      (u.full_name||'').toLowerCase().includes(term) ||
      (u.designation||'').toLowerCase().includes(term) ||
      (u.role||'').toLowerCase().includes(term) ||
      (u.email||'').toLowerCase().includes(term) ||
      (u.user_id||'').toLowerCase().includes(term)
    );
    if (count) count.textContent = filtered.length + ' / ' + _allUsersCache.length + ' users';
    _renderUserCards(filtered);
  }

  // ── Colleague Profile Viewer (Facebook-style card, opened from a Users
  // Directory click) — depth shown is decided server-side by
  // getColleagueProfile based on the VIEWER's own role, never toggled
  // client-side: HR/VP/Admin/Principal/Cord see the full personnel record,
  // everyone else sees a curated summary. The completion % badge is the
  // same either way — it reflects the profile itself, not what this
  // viewer happens to be allowed to see.
  function openColleagueProfile(teacherId) {
    const modal = document.getElementById('colleagueProfileModal');
    const body = document.getElementById('colleagueProfileBody');
    if (!modal || !body) return;
    body.innerHTML = `<div class="text-center py-16"><i data-lucide="loader-2" class="h-6 w-6 animate-spin inline text-blue-600"></i></div>`;
    lucide.createIcons();
    modal.classList.remove('hidden');
    const myId = window.APP_USER && window.APP_USER.user_id;
    google.script.run
      .withSuccessHandler(res => {
        if (!res || res.result !== 'success') {
          body.innerHTML = `<div class="text-center py-16 text-slate-400 text-xs font-black uppercase">${(res && res.error) || 'Could not load this profile.'}</div>`;
          return;
        }
        body.innerHTML = _renderColleagueProfile(res.profile, res.completion, res.isPrivileged, res.canEditCareer);
        lucide.createIcons();
      })
      .withFailureHandler(() => {
        body.innerHTML = `<div class="text-center py-16 text-slate-400 text-xs font-black uppercase">Network error — try again.</div>`;
      })
      .getColleagueProfile(myId, teacherId);
  }
  function closeColleagueProfileModal() {
    const modal = document.getElementById('colleagueProfileModal');
    if (modal) modal.classList.add('hidden');
  }

  function _renderColleagueProfile(p, completion, isPrivileged, canEditCareer) {
    const photoSrc = p.photo_url ? (p.photo_url.startsWith('http') ? p.photo_url : 'https://lh3.googleusercontent.com/d/' + p.photo_url) : '';
    const avatarHtml = photoSrc
      ? `<img src="${photoSrc}" class="w-full h-full object-cover" onerror="this.style.display='none'">`
      : `<i data-lucide="user" class="h-11 w-11 text-white"></i>`;
    const pct = Math.max(0, Math.min(100, completion || 0));
    const pctBadgeClass = pct >= 80 ? 'bg-emerald-100 text-emerald-600' : pct >= 40 ? 'bg-amber-100 text-amber-600' : 'bg-rose-100 text-rose-600';
    const pctBarColor = pct >= 80 ? '#10b981' : pct >= 40 ? '#f59e0b' : '#ef4444';
    const dateOnly = v => v ? String(v).split('T')[0] : '';

    // Same visual language as the owner's own "Preview" mode (prev-section/
    // pv-field, see styles.css) — reused deliberately so this feels like
    // the same product, not a bolted-on second design.
    const sec = (icon, title, bodyHtml) => `
      <div class="prev-section">
        <div class="prev-hdr flex items-center gap-1.5"><i data-lucide="${icon}" class="h-3 w-3"></i>${title}</div>
        <div class="prev-body">${bodyHtml}</div>
      </div>`;
    const fld = (label, value) => `<div class="pv-field"><p class="pv-lbl">${label}</p><p class="pv-val${value ? '' : ' empty'}">${value || '—'}</p></div>`;
    const grid = (...cells) => `<div class="grid grid-cols-2 md:grid-cols-3 gap-4">${cells.join('')}</div>`;
    // Only render a section if at least one of its fields actually has a value.
    const any = (...vals) => vals.some(v => v !== null && v !== undefined && String(v).trim() !== '');

    const edu = Array.isArray(p.education_records) ? p.education_records : [];
    const eduSection = (edu.length || p.additional_qualification) ? sec('graduation-cap', 'Education', `
      ${edu.length ? `<div class="flex flex-col gap-2 mb-3">
        ${edu.map(e => `<div class="text-sm"><span class="font-black text-slate-700">${e.exam_passed || e.school_college || ''}</span>${e.school_college && e.exam_passed ? ` <span class="text-slate-400 font-bold">— ${e.school_college}</span>` : ''}${e.year_of_passing ? ` <span class="text-slate-400 font-bold">(${e.year_of_passing})</span>` : ''}${e.division_gpa ? ` <span class="text-slate-400 font-bold">· ${e.division_gpa}</span>` : ''}</div>`).join('')}
      </div>` : ''}
      ${p.additional_qualification ? fld('Additional Qualification', p.additional_qualification) : ''}
    `) : '';

    const workSection = sec('briefcase', 'Work', grid(
      fld('Department / School', p.school_college), fld('Category', p.category), fld('Joined', dateOnly(p.joining_date)),
      fld('Mobile', p.mobile || p.tt_phone), fld('Email', p.personal_email)
    ));

    if (!isPrivileged) {
      return _colleagueProfileShell(p, pct, pctBadgeClass, pctBarColor, `${workSection}${eduSection}`);
    }

    // ── Full personnel record (HR/VP/Admin/Principal/Cord, or your own card) ──
    const sp = (Array.isArray(p.spouse_details) && p.spouse_details[0]) || {};
    const siblings = Array.isArray(p.siblings_info) ? p.siblings_info : [];
    const children = Array.isArray(p.children_info) ? p.children_info : [];
    const family = Array.isArray(p.family_details) ? p.family_details : [];
    const countries = Array.isArray(p.countries_visited) ? p.countries_visited : [];
    const languages = Array.isArray(p.language_skills) ? p.language_skills : [];
    const tbl = (headers, rows, cellsFn) => rows.length ? `<div class="overflow-x-auto -mx-1"><table class="w-full text-left border-collapse text-xs">
        <thead><tr class="border-b border-slate-100">${headers.map(h => `<th class="px-1 py-1.5 pv-lbl">${h}</th>`).join('')}</tr></thead>
        <tbody>${rows.map(r => `<tr class="border-b border-slate-50">${cellsFn(r).map(c => `<td class="px-1 py-1.5 font-bold text-slate-700">${c || '—'}</td>`).join('')}</tr>`).join('')}</tbody>
      </table></div>` : '<p class="pv-val empty text-xs">No records.</p>';

    const identitySection = any(p.national_id, p.auth_ref, p.tid_bin_no) ? sec('id-card', 'Identity & Registration', grid(
      fld('National ID', p.national_id), fld('Auth Ref', p.auth_ref), fld('TID / BIN No.', p.tid_bin_no)
    )) : '';

    const birthSection = any(p.date_of_birth, p.place_of_birth, p.birth_certificate_no, p.height_feet, p.weight_kg, p.blood_group, p.identification_marks, p.religion, p.caste) ? sec('heart-pulse', 'Birth, Physical & Blood', grid(
      fld('Date of Birth', dateOnly(p.date_of_birth)), fld('Place of Birth', p.place_of_birth), fld('Birth Certificate No.', p.birth_certificate_no),
      fld('Height', p.height_feet ? `${p.height_feet}' ${p.height_inches || 0}"` : ''), fld('Weight', p.weight_kg ? `${p.weight_kg} kg` : ''), fld('Blood Group', p.blood_group),
      fld('Identification Marks', p.identification_marks), fld('Religion', p.religion), fld('Caste', p.caste)
    )) : '';

    const contactSection = any(p.nationality, p.permanent_address, p.present_address, p.alternate_address) ? sec('map-pin', 'Nationality & Address', grid(
      fld('Nationality', p.nationality), fld('Permanent Address', p.permanent_address), fld('Present Address', p.present_address), fld('Alternate Address', p.alternate_address)
    )) : '';

    const parentsSection = any(p.father_name, p.mother_name, p.position_in_siblings) || siblings.length ? sec('users', 'Family — Parents & Siblings', `
      ${any(p.father_name, p.father_occupation, p.father_nationality) ? `<p class="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-2">Father</p>${grid(fld('Name', p.father_name), fld('Occupation', p.father_occupation), fld('Nationality', p.father_nationality))}<div class="my-3"></div>` : ''}
      ${any(p.mother_name, p.mother_occupation, p.mother_nationality) ? `<p class="text-[10px] font-black text-pink-500 uppercase tracking-widest mb-2">Mother</p>${grid(fld('Name', p.mother_name), fld('Occupation', p.mother_occupation), fld('Nationality', p.mother_nationality))}<div class="my-3"></div>` : ''}
      ${siblings.length ? `<p class="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-1">Brothers &amp; Sisters</p>${tbl(['Name', 'Age', 'Occupation / Address'], siblings, r => [r.name, r.age, r.occupation_address])}` : ''}
      ${p.position_in_siblings ? `<div class="mt-3">${fld('Position within Siblings', p.position_in_siblings)}</div>` : ''}
    `) : '';

    const maritalSection = any(p.marital_status, sp.name_english, sp.occupation) || family.length ? sec('heart', 'Marital &amp; Spouse', `
      ${grid(fld('Marital Status', p.marital_status), fld('Marriage / Divorce Date', dateOnly(p.marriage_divorce_date)))}
      ${any(sp.name_english, sp.occupation, sp.educational_qualification) ? `<div class="mt-3">${grid(fld('Spouse Name', sp.name_english), fld('Spouse Occupation', sp.occupation), fld('Spouse Education', sp.educational_qualification))}</div>` : ''}
      ${family.length ? `<p class="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-3">Basic Family Record</p>${tbl(['Relation', 'Name', 'Date'], family, r => [r.member_type, r.name, dateOnly(r.marriage_date)])}` : ''}
    `) : '';

    const childrenSection = children.length ? sec('baby', 'Particulars of Children', tbl(['Name', 'Sex', 'Date of Birth', 'Occupation'], children, r => [r.name, r.sex, dateOnly(r.date_of_birth), r.occupation])) : '';

    const financialSection = any(p.own_income) ? sec('banknote', 'Financial', grid(fld('Own Income', p.own_income))) : '';

    const travelSection = any(p.passport_number, p.passport_type) || countries.length || languages.length ? sec('plane', 'Travel &amp; Languages', `
      ${any(p.passport_number) ? grid(fld('Passport Number', p.passport_number), fld('Type', p.passport_type), fld('Date of Expiry', dateOnly(p.passport_date_expiry))) : ''}
      ${countries.length ? `<p class="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 mt-3">Countries Visited</p>${tbl(['Country', 'From', 'To'], countries, r => [r.country_name, dateOnly(r.duration_from), dateOnly(r.duration_to)])}` : ''}
      ${languages.length ? `<div class="flex flex-wrap gap-2 mt-3">${languages.map(l => `<span class="px-3 py-1.5 bg-blue-50 rounded-xl text-xs font-black text-blue-700">${l.language}${l.efficiency ? ` · ${l.efficiency}` : ''}</span>`).join('')}</div>` : ''}
    `) : '';

    // Career notes are HR-disciplinary in nature — visible only alongside
    // the rest of the full record, editable only when canEditCareer (never
    // for your own card, even if you hold an eligible role), and readable
    // history is always one click away for accountability.
    const careerSection = sec('lock', 'Career Record', `
      <div class="flex items-center justify-between mb-2 -mt-1">
        ${canEditCareer ? '<p class="text-[10px] text-slate-400 font-bold">Editable — every change is logged.</p>' : '<p class="text-[10px] text-slate-400 font-bold">Read-only — only HR, VP, Principal, or Cord may edit, and never their own.</p>'}
        <button onclick="toggleCareerHistory('${p.teacher_id}')" class="text-[9px] font-black text-blue-600 uppercase tracking-widest hover:underline shrink-0 ml-3">View History</button>
      </div>
      <div class="flex flex-col gap-3">
        <div>
          <label class="pv-lbl mb-1 block">Breaking Institution Law</label>
          <textarea id="ccInstLaw" rows="2" ${canEditCareer ? '' : 'readonly'} class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs resize-y">${p.institution_law_breaking || ''}</textarea>
        </div>
        <div>
          <label class="pv-lbl mb-1 block">Breaking Civil Law</label>
          <textarea id="ccCivilLaw" rows="2" ${canEditCareer ? '' : 'readonly'} class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs resize-y">${p.civil_law_breaking || ''}</textarea>
        </div>
        ${canEditCareer ? `<button onclick="saveColleagueCareerFields('${p.teacher_id}')" class="self-end px-4 py-2 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all">Save Career Notes</button>` : ''}
      </div>
      <div id="careerHistoryPanel" class="hidden mt-3 pt-3 border-t border-dashed border-slate-200"></div>
    `);

    const allSections = [workSection, identitySection, birthSection, contactSection, parentsSection, maritalSection, childrenSection, financialSection, travelSection, eduSection, careerSection].join('');
    return _colleagueProfileShell(p, pct, pctBadgeClass, pctBarColor, allSections);
  }

  function _colleagueProfileShell(p, pct, pctBadgeClass, pctBarColor, sectionsHtml) {
    const photoSrc = p.photo_url ? (p.photo_url.startsWith('http') ? p.photo_url : 'https://lh3.googleusercontent.com/d/' + p.photo_url) : '';
    const avatarHtml = photoSrc
      ? `<img src="${photoSrc}" class="w-full h-full object-cover" onerror="this.style.display='none'">`
      : `<i data-lucide="user" class="h-11 w-11 text-white"></i>`;
    return `
      <div>
        <div class="h-28 relative" style="background:linear-gradient(120deg,#0f172a 0%,#1e3a8a 55%,#1d4ed8 100%)">
          <div class="absolute inset-0 opacity-20" style="background-image:radial-gradient(circle at 20% 30%, white 1px, transparent 1px);background-size:18px 18px"></div>
        </div>
        <div class="px-6 pb-6 bg-white">
          <div class="flex items-end justify-between -mt-11">
            <div class="w-22 h-22 rounded-2xl overflow-hidden border-4 border-white bg-gradient-to-tr from-blue-600 to-indigo-500 flex items-center justify-center shadow-lg" style="width:5.5rem;height:5.5rem">
              ${avatarHtml}
            </div>
            <div class="px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${pctBadgeClass} mb-1">${pct}% Complete</div>
          </div>
          <div class="mt-3">
            <h3 class="text-xl font-black text-slate-800 tracking-tight">${p.full_name || p.teacher_id || '—'}</h3>
            ${p.name_bengali ? `<p class="text-slate-400 font-bold text-xs mt-0.5">${p.name_bengali}</p>` : ''}
            ${p.designation ? `<p class="text-blue-600 font-black text-xs uppercase tracking-wide mt-1.5">${p.designation}</p>` : ''}
          </div>
          <div class="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden mt-3">
            <div class="h-full rounded-full transition-all" style="width:${pct}%;background:${pctBarColor}"></div>
          </div>
        </div>
        <div class="px-6 pb-6 pt-1 bg-slate-50 flex flex-col gap-3">
          ${sectionsHtml}
        </div>
      </div>`;
  }

  function saveColleagueCareerFields(teacherId) {
    const inst = document.getElementById('ccInstLaw');
    const civil = document.getElementById('ccCivilLaw');
    if (!inst || !civil) return;
    const myId = window.APP_USER && window.APP_USER.user_id;
    google.script.run.withSuccessHandler(function (res) {
      if (res && res.result === 'success') showToast(res.changed ? 'Career record updated' : 'No changes to save');
      else showToast((res && res.error) || 'Failed to save', 'error');
    }).withFailureHandler(function () {
      showToast('Network error', 'error');
    }).saveColleagueCareer(myId, teacherId, inst.value.trim(), civil.value.trim());
  }

  function toggleCareerHistory(teacherId) {
    const panel = document.getElementById('careerHistoryPanel');
    if (!panel) return;
    if (!panel.classList.contains('hidden')) { panel.classList.add('hidden'); return; }
    panel.classList.remove('hidden');
    panel.innerHTML = `<p class="text-center text-slate-400 text-xs font-black uppercase py-3">Loading…</p>`;
    const myId = window.APP_USER && window.APP_USER.user_id;
    google.script.run.withSuccessHandler(function (res) {
      if (!res || res.result !== 'success') { panel.innerHTML = `<p class="text-center text-slate-400 text-xs font-bold py-3">${(res && res.error) || 'Could not load history.'}</p>`; return; }
      const hist = res.history || [];
      if (!hist.length) { panel.innerHTML = `<p class="text-center text-slate-400 text-xs font-bold py-3">No edits recorded yet.</p>`; return; }
      panel.innerHTML = `<p class="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Edit History</p>` +
        hist.map(h => `<div class="text-xs mb-2 pb-2 border-b border-slate-50">
          <span class="font-black text-slate-700">${h.field === 'institution_law_breaking' ? 'Institution Law' : 'Civil Law'}</span>
          <span class="text-slate-400"> by ${h.editor_user_id} on ${new Date(h.created_at).toLocaleString()}</span>
          <div class="text-slate-500 mt-0.5"><span class="line-through text-red-400">${h.old_value || '(empty)'}</span> → <span class="text-emerald-600 font-bold">${h.new_value || '(empty)'}</span></div>
        </div>`).join('');
    }).withFailureHandler(function () {
      panel.innerHTML = `<p class="text-center text-red-400 text-xs font-bold py-3">Network error.</p>`;
    }).getCareerEditHistory(myId, teacherId);
  }

  // ═══════════════════════════════════════════════════════
  //  MESSAGING CENTER — two-pane inbox + conversation threads
  // ═══════════════════════════════════════════════════════

  let _msgConvCache   = [];     // conversations from getMessagingOverview
  let _msgPeopleCache = [];     // all faculty (for starting new chats)
  let _activePartnerId = null;  // currently open conversation
  let _msgThreadPoll  = null;
  let _msgListPoll    = null;
  let _lastUnreadDm   = 0;
  let _sbClient       = null;   // Supabase Realtime client
  let _sbChannel      = null;   // own broadcast channel subscription

  function _photoUrl(raw) {
    if (!raw) return '';
    return raw.startsWith('http') ? raw : 'https://lh3.googleusercontent.com/d/' + raw;
  }

  // Avatar markup: photo if available, else gradient + initial
  function _avatar(name, photo, sizeClass, presenceCls) {
    const src = _photoUrl(photo);
    const inner = src
      ? `<img src="${src}" class="w-full h-full object-cover absolute inset-0" onerror="this.style.display='none'">`
      : `<span class="text-white font-black">${(name||'?').trim().charAt(0).toUpperCase()}</span>`;
    const dot = presenceCls ? `<span class="absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-white ${presenceCls}"></span>` : '';
    return `<div class="relative shrink-0">
      <div class="${sizeClass} rounded-xl overflow-hidden relative bg-gradient-to-tr from-blue-600 to-indigo-500 flex items-center justify-center">${inner}</div>
      ${dot}
    </div>`;
  }

  // Smart timestamps. compact = short form for list rows.
  function _smartTime(dateStr, compact) {
    if (!dateStr) return '';
    const d = new Date(dateStr), now = new Date();
    const sameDay = d.toDateString() === now.toDateString();
    const yest = new Date(now); yest.setDate(now.getDate()-1);
    const isYest = d.toDateString() === yest.toDateString();
    const t = d.toLocaleTimeString('en-BD',{hour:'2-digit',minute:'2-digit',hour12:true});
    if (sameDay) return t;
    if (isYest)  return compact ? 'Yesterday' : 'Yesterday ' + t;
    const sameYear = d.getFullYear() === now.getFullYear();
    const dateP = d.toLocaleDateString('en-BD',{day:'2-digit',month:'short',...(sameYear?{}:{year:'numeric'})});
    return compact ? dateP : dateP + ' ' + t;
  }

  function _partnerInfo(id) {
    return _msgConvCache.find(c => c.partner_id === id)
        || _msgPeopleCache.find(p => p.user_id === id)
        || { full_name: id, photo_url: null, designation: null, last_active: null };
  }

  // ── Main view ──────────────────────────────────────────
  function loadMessagesView() {
    _setViewHash('messages');
    setActiveNavLink('nav-messages');
    setContentHeader('Messages', 'message-square');
    _activePartnerId = null;
    const container = document.getElementById('view-container');
    if (!container) return;
    container.innerHTML = `
      <div id="msgRoot" class="flex bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden mt-2"
           style="height:calc(100dvh - 120px);min-height:420px;">
        <!-- Conversation list pane -->
        <div id="msgListPane" class="flex flex-col w-full md:w-80 md:border-r border-slate-100 shrink-0">
          <div class="p-3 border-b border-slate-100 shrink-0 flex items-center justify-between gap-2">
            <p class="font-black text-slate-800 text-sm uppercase tracking-widest">Chats</p>
            <button onclick="openNewMessage()" title="New message"
              class="flex items-center gap-1.5 pl-2.5 pr-3 py-2 bg-blue-600 hover:bg-black text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shrink-0">
              <i data-lucide="message-square-plus" class="h-3.5 w-3.5"></i> Message
            </button>
          </div>
          <div class="px-3 pt-3 pb-2 shrink-0">
            <div class="relative">
              <i data-lucide="search" class="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-400 pointer-events-none"></i>
              <input id="msgSearch" type="search" placeholder="Search people to message…"
                autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" name="ccpc-msg-search"
                oninput="filterMessagePeople(this.value)"
                class="w-full pl-9 pr-3 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-600 transition-all">
            </div>
          </div>
          <div id="msgConvList" class="flex-1 overflow-y-auto custom-scrollbar-light">
            <div class="text-center py-12 text-slate-300 text-xs font-black uppercase tracking-widest">Loading…</div>
          </div>
        </div>
        <!-- Thread pane -->
        <div id="msgThreadPane" class="flex-col flex-1 min-w-0">
          <div id="msgThreadEmpty" class="flex-1 flex flex-col items-center justify-center text-slate-300 gap-3 p-8">
            <div class="w-16 h-16 rounded-2xl bg-slate-50 flex items-center justify-center"><i data-lucide="messages-square" class="h-7 w-7"></i></div>
            <p class="text-xs font-black uppercase tracking-widest">Select a conversation</p>
            <p class="text-[10px] font-bold text-slate-300">or search a name to start a new one</p>
          </div>
          <div id="msgThreadActive" class="hidden flex-col h-full" style="height:100%;"></div>
        </div>
      </div>`;
    lucide.createIcons();
    // Browsers sometimes autofill this field with the login credential; clear it forcefully
    const _msBox = document.getElementById('msgSearch');
    if (_msBox) { _msBox.value = ''; setTimeout(() => { if (_msBox) _msBox.value = ''; }, 200); }
    _loadConversations(false);
    refreshMessagesBadge();

    // Fallback poll — Realtime handles instant updates; this catches WebSocket gaps
    clearInterval(_msgListPoll);
    _msgListPoll = setInterval(() => {
      if (!document.getElementById('msgConvList')) { clearInterval(_msgListPoll); return; }
      const box = document.getElementById('msgSearch');
      if (box && box.value.trim()) return;   // don't clobber an active people search
      _loadConversations(true);
    }, 60000);
  }

  function openMessagesPanel() { loadMessagesView(); }

  function _loadConversations(silent) {
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run
      .withSuccessHandler(res => {
        _msgConvCache = (res && Array.isArray(res.conversations)) ? res.conversations : [];
        _updateMsgBadges(res ? res.totalUnread : 0);
        const box = document.getElementById('msgSearch');
        if (box && box.value.trim()) return;  // user is searching — leave list alone
        _renderConversationList();
      })
      .withFailureHandler(() => {
        if (silent) return;
        const list = document.getElementById('msgConvList');
        if (list) list.innerHTML = `<div class="text-center py-8 text-red-400 text-xs font-black uppercase">Failed to load</div>`;
      })
      .getMessagingOverview(myId);
  }

  function _renderConversationList() {
    const list = document.getElementById('msgConvList');
    if (!list) return;
    if (!_msgConvCache.length) {
      list.innerHTML = `<div class="text-center py-12 px-4 text-slate-300 text-xs font-black uppercase tracking-widest">No conversations yet.<br><span class="text-[10px] text-slate-300 normal-case font-bold tracking-normal">Search a name above to start one.</span></div>`;
      return;
    }
    const myId = window.APP_USER && window.APP_USER.user_id;
    list.innerHTML = _msgConvCache.map(c => {
      const { cls } = _presenceInfo(c.last_active);
      const active = c.partner_id === _activePartnerId;
      const preview = (c.last_sender_id === myId ? 'You: ' : '') + (c.last_message || '');
      return `<button onclick="openConversation('${String(c.partner_id).replace(/'/g,"\\'")}')"
        class="w-full flex items-center gap-3 px-3 py-3 border-b border-slate-50 text-left transition-colors ${active ? 'bg-blue-50' : 'hover:bg-slate-50'}">
        ${_avatar(c.full_name, c.photo_url, 'w-11 h-11', cls)}
        <div class="flex-1 min-w-0">
          <div class="flex items-center justify-between gap-2">
            <p class="font-black text-slate-800 text-sm truncate">${_escHtml(c.full_name)}</p>
            <span class="text-[9px] text-slate-400 font-bold shrink-0">${_smartTime(c.last_message_at, true)}</span>
          </div>
          <div class="flex items-center justify-between gap-2 mt-0.5">
            <p class="text-[11px] ${c.unread ? 'text-slate-700 font-black' : 'text-slate-400 font-bold'} truncate">${_escHtml(preview)}</p>
            ${c.unread ? `<span class="shrink-0 min-w-[18px] h-[18px] px-1 bg-blue-600 text-white text-[9px] font-black rounded-full flex items-center justify-center">${c.unread>99?'99+':c.unread}</span>` : ''}
          </div>
        </div>
      </button>`;
    }).join('');
    lucide.createIcons();
  }

  // Search switches the left pane to "start a new chat" people results
  function filterMessagePeople(q) {
    const term = (q||'').toLowerCase().trim();
    const list = document.getElementById('msgConvList');
    if (!list) return;
    if (!term) { _renderConversationList(); return; }

    const render = () => {
      const myId = window.APP_USER && window.APP_USER.user_id;
      const matches = _msgPeopleCache.filter(u => u.user_id !== myId && (
        (u.full_name||'').toLowerCase().includes(term) ||
        (u.designation||'').toLowerCase().includes(term) ||
        (u.role||'').toLowerCase().includes(term) ||
        (u.user_id||'').toLowerCase().includes(term)
      )).slice(0, 50);
      if (!matches.length) {
        list.innerHTML = `<div class="text-center py-12 text-slate-300 text-xs font-black uppercase tracking-widest">No people found</div>`;
        return;
      }
      list.innerHTML = `<p class="px-3 pt-3 pb-1 text-[9px] font-black text-slate-400 uppercase tracking-widest">Start a conversation</p>` +
        matches.map(u => {
          const { cls } = _presenceInfo(u.last_active);
          return `<button onclick="openConversation('${String(u.user_id).replace(/'/g,"\\'")}')"
            class="w-full flex items-center gap-3 px-3 py-2.5 border-b border-slate-50 text-left hover:bg-slate-50 transition-colors">
            ${_avatar(u.full_name, u.photo_url, 'w-9 h-9', cls)}
            <div class="flex-1 min-w-0">
              <p class="font-black text-slate-800 text-xs truncate">${_escHtml(u.full_name || u.user_id)}</p>
              ${u.designation ? `<p class="text-[9px] text-blue-600 font-bold uppercase tracking-wide truncate">${_escHtml(u.designation)}</p>` : ''}
            </div>
            <i data-lucide="message-circle" class="h-4 w-4 text-slate-300"></i>
          </button>`;
        }).join('');
      lucide.createIcons();
    };

    if (_msgPeopleCache.length) { render(); }
    else {
      list.innerHTML = `<div class="text-center py-12 text-slate-300 text-xs font-black uppercase tracking-widest">Loading people…</div>`;
      google.script.run
        .withSuccessHandler(users => { _msgPeopleCache = Array.isArray(users) ? users : []; render(); })
        .withFailureHandler(() => { list.innerHTML = `<div class="text-center py-8 text-red-400 text-xs font-black uppercase">Failed to load people</div>`; })
        .getAllUsersWithPresence();
    }
  }

  // ── New-message composer: pick anyone in the faculty ──
  function openNewMessage() {
    let modal = document.getElementById('newMsgModal');
    if (!modal) {
      modal = document.createElement('div');
      modal.id = 'newMsgModal';
      modal.style.cssText = 'position:fixed;inset:0;z-index:9600;background:rgba(15,23,42,.5);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;padding:1rem;';
      modal.onclick = e => { if (e.target === modal) closeNewMessage(); };
      document.body.appendChild(modal);
    }
    modal.innerHTML = `
      <div style="width:min(440px,100%);max-height:82vh;background:#fff;border-radius:1.5rem;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.25);">
        <div class="flex items-center justify-between px-5 py-4 border-b border-slate-100 shrink-0">
          <div>
            <p class="font-black text-slate-800 text-base">New Message</p>
            <p class="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Pick someone to message</p>
          </div>
          <button onclick="closeNewMessage()" class="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-100 hover:bg-red-100 hover:text-red-500 text-slate-400 transition-all font-black text-lg leading-none">×</button>
        </div>
        <div class="p-3 border-b border-slate-100 shrink-0">
          <div class="relative">
            <i data-lucide="search" class="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-400 pointer-events-none"></i>
            <input id="newMsgSearch" type="search" placeholder="Search by name, designation, role…"
              autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" name="ccpc-newmsg-search"
              oninput="filterNewMessage(this.value)"
              class="w-full pl-9 pr-3 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-600 transition-all">
          </div>
        </div>
        <div id="newMsgList" class="flex-1 overflow-y-auto custom-scrollbar-light min-h-[220px]">
          <div class="text-center py-12 text-slate-300 text-xs font-black uppercase tracking-widest">Loading people…</div>
        </div>
      </div>`;
    lucide.createIcons();
    setTimeout(() => { const s = document.getElementById('newMsgSearch'); if (s) s.focus(); }, 60);

    if (_msgPeopleCache.length) { _renderNewMessageList(''); }
    else {
      google.script.run
        .withSuccessHandler(u => { _msgPeopleCache = Array.isArray(u) ? u : []; _renderNewMessageList(''); })
        .withFailureHandler(() => { const l = document.getElementById('newMsgList'); if (l) l.innerHTML = `<div class="text-center py-8 text-red-400 text-xs font-black uppercase">Failed to load people</div>`; })
        .getAllUsersWithPresence();
    }
  }

  function closeNewMessage() {
    const m = document.getElementById('newMsgModal');
    if (m) m.remove();
  }

  function filterNewMessage(q) { _renderNewMessageList(q); }

  function _renderNewMessageList(q) {
    const list = document.getElementById('newMsgList');
    if (!list) return;
    const term = (q||'').toLowerCase().trim();
    const myId = window.APP_USER && window.APP_USER.user_id;
    const people = _msgPeopleCache.filter(u => u.user_id !== myId && (!term ||
      (u.full_name||'').toLowerCase().includes(term) ||
      (u.designation||'').toLowerCase().includes(term) ||
      (u.role||'').toLowerCase().includes(term) ||
      (u.user_id||'').toLowerCase().includes(term)
    ));
    if (!people.length) {
      list.innerHTML = `<div class="text-center py-12 text-slate-300 text-xs font-black uppercase tracking-widest">No people found</div>`;
      return;
    }
    list.innerHTML = people.slice(0, 100).map(u => {
      const { cls } = _presenceInfo(u.last_active);
      return `<button onclick="closeNewMessage();openConversation('${String(u.user_id).replace(/'/g,"\\'")}')"
        class="w-full flex items-center gap-3 px-4 py-2.5 border-b border-slate-50 text-left hover:bg-slate-50 transition-colors">
        ${_avatar(u.full_name, u.photo_url, 'w-10 h-10', cls)}
        <div class="flex-1 min-w-0">
          <p class="font-black text-slate-800 text-sm truncate">${_escHtml(u.full_name || u.user_id)}</p>
          ${u.designation ? `<p class="text-[9px] text-blue-600 font-bold uppercase tracking-wide truncate">${_escHtml(u.designation)}</p>` : ''}
        </div>
        <i data-lucide="send" class="h-4 w-4 text-slate-300 shrink-0"></i>
      </button>`;
    }).join('');
    lucide.createIcons();
  }

  // ── Conversation thread ────────────────────────────────
  function openConversation(partnerId) {
    _activePartnerId = partnerId;
    const info = _partnerInfo(partnerId);
    const { cls, label } = _presenceInfo(info.last_active);
    const mobile = window.innerWidth < 768;

    // mobile: swap panes. threadPane's default visibility (hidden on mobile,
    // flex on desktop) is defined in styles.css by #id, and shown here via a
    // plain "msg-open" class rather than Tailwind's `hidden`/`md:flex` —
    // app.html's global `.hidden{display:none!important}` always beats a
    // non-important md:flex regardless of viewport, so that combination would
    // leave the pane invisible on desktop too, forever, since desktop never
    // removes a literal `hidden` class from it.
    const listPane = document.getElementById('msgListPane');
    const threadPane = document.getElementById('msgThreadPane');
    if (threadPane) threadPane.classList.add('msg-open');
    if (mobile && listPane) listPane.classList.add('hidden');
    const empty = document.getElementById('msgThreadEmpty');
    const active = document.getElementById('msgThreadActive');
    if (empty) empty.classList.add('hidden');
    if (!active) return;
    active.classList.remove('hidden');
    active.classList.add('flex');

    const rawNum = (info.whatsapp || info.phone || '').trim();
    const telNum = rawNum.replace(/[\s\-()]/g,'');   // keep + for dialer
    const waNum  = rawNum.replace(/\D/g,'');          // digits only for wa.me
    const callBtns = rawNum ? `
      <a href="tel:${telNum}" title="Call ${_escHtml(rawNum)}" class="w-9 h-9 flex items-center justify-center rounded-xl bg-slate-100 hover:bg-blue-600 hover:text-white text-slate-500 transition-all shrink-0"><i data-lucide="phone" class="h-4 w-4"></i></a>
      <a href="https://wa.me/${waNum}" target="_blank" title="WhatsApp ${_escHtml(rawNum)}" class="w-9 h-9 flex items-center justify-center rounded-xl bg-slate-100 hover:bg-emerald-500 hover:text-white text-slate-500 transition-all shrink-0"><i data-lucide="message-circle" class="h-4 w-4"></i></a>` : '';
    active.innerHTML = `
      <div class="flex items-center gap-3 px-4 py-3 border-b border-slate-100 shrink-0 bg-white">
        <button onclick="backToMessageList()" class="md:hidden w-8 h-8 flex items-center justify-center rounded-lg hover:bg-slate-100 text-slate-500 shrink-0"><i data-lucide="arrow-left" class="h-4 w-4"></i></button>
        ${_avatar(info.full_name, info.photo_url, 'w-10 h-10', cls)}
        <div class="flex-1 min-w-0">
          <p class="font-black text-slate-800 text-sm truncate">${_escHtml(info.full_name)}</p>
          <p class="text-[10px] font-bold truncate ${label==='Active now'?'text-emerald-500':'text-slate-400'}">${info.designation ? _escHtml(info.designation)+' · ' : ''}${label}</p>
        </div>
        ${callBtns}
      </div>
      <div id="msgThreadBody" class="flex-1 overflow-y-auto px-4 py-4 space-y-1 bg-slate-50/50">
        <p class="text-center text-xs text-slate-300 font-black uppercase tracking-widest py-8">Loading…</p>
      </div>
      <div id="msgTypingIndicator" class="hidden px-5 py-1">
        <span class="text-xs text-slate-400 italic">typing…</span>
      </div>
      <div class="p-3 border-t border-slate-100 shrink-0 flex items-end gap-2 bg-white">
        <textarea id="msgComposerInput" rows="1" placeholder="Type a message…" maxlength="2000"
          oninput="this.style.height='auto';this.style.height=Math.min(this.scrollHeight,120)+'px';_broadcastTyping();"
          onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendMessageInThread();}"
          class="flex-1 px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-600 transition-all resize-none leading-snug" style="max-height:120px;"></textarea>
        <button onclick="sendMessageInThread()" class="w-10 h-10 flex items-center justify-center bg-blue-600 text-white rounded-2xl hover:bg-black transition-all shrink-0"><i data-lucide="send" class="h-4 w-4"></i></button>
      </div>`;
    lucide.createIcons();
    _renderConversationList(); // refresh highlight
    _refreshThread(partnerId, false);
    const inp = document.getElementById('msgComposerInput');
    if (inp && !mobile) inp.focus();

    // Fallback poll for open thread — Realtime handles instant updates
    clearInterval(_msgThreadPoll);
    _msgThreadPoll = setInterval(() => {
      if (!document.getElementById('msgThreadBody') || _activePartnerId !== partnerId) { clearInterval(_msgThreadPoll); return; }
      _refreshThread(partnerId, true);
    }, 30000);
  }

  function backToMessageList() {
    _activePartnerId = null;
    clearInterval(_msgThreadPoll);
    const listPane = document.getElementById('msgListPane');
    const threadPane = document.getElementById('msgThreadPane');
    if (listPane) listPane.classList.remove('hidden');
    if (threadPane) threadPane.classList.remove('msg-open');
    _renderConversationList();
  }

  function _refreshThread(partnerId, silent) {
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run
      .withSuccessHandler(msgs => {
        if (_activePartnerId !== partnerId) return;
        _renderThread(Array.isArray(msgs) ? msgs : [], myId, silent);
        // mark incoming as read, then refresh badges + list
        google.script.run.withSuccessHandler(() => {
          _loadConversations(true);
        }).withFailureHandler(()=>{}).markDmRead(myId, partnerId);
      })
      .withFailureHandler(() => {
        if (silent) return;
        const body = document.getElementById('msgThreadBody');
        if (body) body.innerHTML = `<p class="text-center text-xs text-red-400 font-black uppercase py-8">Failed to load messages</p>`;
      })
      .getConversation(myId, partnerId);
  }

  function _renderThread(msgs, myId, silent) {
    const body = document.getElementById('msgThreadBody');
    if (!body) return;
    // preserve scroll position if user scrolled up during a silent refresh
    const nearBottom = body.scrollHeight - body.scrollTop - body.clientHeight < 60;

    if (!msgs.length) {
      body.innerHTML = `<p class="text-center text-xs text-slate-300 font-black uppercase tracking-widest py-8">No messages yet. Say hello! 👋</p>`;
      return;
    }
    let lastDate = '';
    body.innerHTML = msgs.map(m => {
      const d = new Date(m.created_at);
      const dateKey = d.toDateString();
      let sep = '';
      if (dateKey !== lastDate) {
        lastDate = dateKey;
        const now = new Date();
        const yest = new Date(now); yest.setDate(now.getDate()-1);
        let dl = d.toDateString()===now.toDateString() ? 'Today'
               : d.toDateString()===yest.toDateString() ? 'Yesterday'
               : d.toLocaleDateString('en-BD',{day:'2-digit',month:'short',year:'numeric'});
        sep = `<div class="flex justify-center my-3"><span class="px-3 py-1 bg-slate-200/70 text-slate-500 text-[9px] font-black uppercase tracking-widest rounded-full">${dl}</span></div>`;
      }
      const isMine = m.sender_id === myId;
      const time = d.toLocaleTimeString('en-BD',{hour:'2-digit',minute:'2-digit',hour12:true});
      const receipt = isMine ? `<i data-lucide="${m.is_read ? 'check-check' : 'check'}" class="h-3 w-3 ${m.is_read ? 'text-sky-300' : 'text-blue-200'} inline-block ml-1 align-middle"></i>` : '';
      const del = isMine ? `<button onclick="deleteDirectMsg('${m.id}')" class="opacity-0 group-hover/msg:opacity-100 transition-opacity text-blue-200 hover:text-white ml-1" title="Delete"><i data-lucide="trash-2" class="h-3 w-3"></i></button>` : '';
      return `${sep}<div class="flex ${isMine ? 'justify-end' : 'justify-start'} group/msg">
        <div class="max-w-[78%] px-3.5 py-2 rounded-2xl ${isMine ? 'bg-blue-600 text-white rounded-br-md' : 'bg-white border border-slate-100 text-slate-800 rounded-bl-md shadow-sm'}">
          <p class="text-sm font-medium leading-snug whitespace-pre-wrap break-words">${_escHtml(m.message)}</p>
          <p class="text-[9px] mt-1 ${isMine ? 'text-blue-200' : 'text-slate-400'} font-bold flex items-center justify-end gap-0.5">${time}${receipt}${del}</p>
        </div>
      </div>`;
    }).join('');
    lucide.createIcons();
    if (nearBottom || !silent) body.scrollTop = body.scrollHeight;
  }

  function sendMessageInThread() {
    const myId = window.APP_USER && window.APP_USER.user_id;
    const input = document.getElementById('msgComposerInput');
    const msg = input ? input.value.trim() : '';
    if (!msg || !myId || !_activePartnerId) return;
    const partnerId = _activePartnerId;
    input.value = ''; input.style.height = 'auto'; input.focus();
    // optimistic: surface the conversation in the list right away, with the name,
    // even though the recipient hasn't replied yet
    _upsertConversationLocal(partnerId, msg, myId);
    google.script.run
      .withSuccessHandler(() => { _refreshThread(partnerId, false); _loadConversations(true); })
      .withFailureHandler(() => { showToast('Failed to send message', 'error'); if (input) input.value = msg; })
      .sendDirectMessage(myId, partnerId, msg);
  }

  // Insert or move a conversation to the top of the list locally (before the server round-trip).
  // Pulls the partner's name/photo from whatever we already know (conv cache, people cache, directory seed).
  function _upsertConversationLocal(partnerId, message, myId) {
    const info = _partnerInfo(partnerId);
    let conv = _msgConvCache.find(c => c.partner_id === partnerId);
    if (conv) {
      _msgConvCache = _msgConvCache.filter(c => c.partner_id !== partnerId);
    } else {
      conv = { partner_id: partnerId, unread: 0,
               full_name: info.full_name || partnerId,
               photo_url: info.photo_url || null,
               designation: info.designation || null,
               last_active: info.last_active || null };
    }
    conv.last_message    = message;
    conv.last_message_at = new Date().toISOString();
    conv.last_sender_id  = myId;
    _msgConvCache.unshift(conv);
    const box = document.getElementById('msgSearch');
    if (!(box && box.value.trim())) _renderConversationList();
  }

  function deleteDirectMsg(msgId) {
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run
      .withSuccessHandler(() => { if (_activePartnerId) _refreshThread(_activePartnerId, false); })
      .withFailureHandler(() => showToast('Failed to delete', 'error'))
      .deleteDirectMessage(msgId, myId);
  }

  // Entry point from the Users Directory "Message" button — jumps to the center
  function openDirectMessage(recipientId, recipientName, photoSrc) {
    // seed the partner cache so the thread header has a name/photo immediately
    if (recipientId && !_msgConvCache.find(c => c.partner_id === recipientId)) {
      _msgPeopleCache = _msgPeopleCache.filter(p => p.user_id !== recipientId);
      _msgPeopleCache.push({ user_id: recipientId, full_name: recipientName, photo_url: photoSrc, designation: null, last_active: null });
    }
    loadMessagesView();
    setTimeout(() => openConversation(recipientId), 50);
  }

  // ── Unread badges (nav link + header) ──────────────────
  function _updateMsgBadges(unread) {
    unread = unread || 0;
    ['msgNavBadge','msgHeaderBadge'].forEach(id => {
      const b = document.getElementById(id);
      if (!b) return;
      if (unread > 0) {
        b.textContent = unread > 99 ? '99+' : unread;
        b.classList.remove('hidden');
        b.style.display = 'flex';   // beat any hidden/flex class ordering conflict
      } else {
        b.classList.add('hidden');
        b.style.display = 'none';
      }
    });
    // proactive toast when a new message arrives while away from the thread
    if (unread > _lastUnreadDm && _lastUnreadDm !== 0 && !document.getElementById('msgThreadBody')) {
      showToast('💬 New message received');
    }
    _lastUnreadDm = unread;
  }

  function refreshMessagesBadge() {
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run.withSuccessHandler(n => _updateMsgBadges(typeof n === 'number' ? n : 0))
      .withFailureHandler(()=>{}).countUnreadDms(myId);
  }

  // ═══════════════════════════════════════════════════════
  //  HEARTBEAT — update last_active every 2 minutes
  // ═══════════════════════════════════════════════════════

  function updateLastActiveHeartbeat() {
    const myId = window.APP_USER && window.APP_USER.user_id;
    if (!myId) return;
    google.script.run.withSuccessHandler(() => {}).withFailureHandler(() => {}).updateLastActive(myId);
  }

  // Start heartbeat + initial badge refresh after login (called from launchDashboard / initApp)
  function startSessionHeartbeat() {
    updateLastActiveHeartbeat();
    refreshNotifBadge();
    refreshMessagesBadge();
    setInterval(updateLastActiveHeartbeat, 2 * 60 * 1000);
    setInterval(refreshNotifBadge, 60 * 1000);
    setInterval(refreshMessagesBadge, 30 * 1000);
  }

  // ══════════════════════════════════════════════════════════════════════
  //  ANALYSE SSC RESULT — parses a BISE board result PDF (+ optional student
  //  roster .docx) entirely client-side and generates an aggregated Excel
  //  workbook for download. No server round-trip: PDF text extraction via
  //  PDF.js, roster table extraction via JSZip, workbook writing via the
  //  same SheetJS build already used for the bulk-import feature.
  //
  //  Two PDF layouts are auto-detected:
  //    "detailed" — full subject-wise marks per roll (e.g. BISE Chattogram's
  //                 institution printout: 116285[5.00]:101:T:142(A ),...)
  //    "simple"   — roll + GPA only, no subject marks (e.g. the shorter
  //                 "roll[gpa], roll[gpa], ... =N" printout)
  //  Output is always the same 6-sheet workbook shape regardless of which
  //  layout/roster data is available — missing data shows "-" or a short
  //  note instead of the sheet/columns being dropped, so files stay
  //  consistent to compare across schools/years.
  // ══════════════════════════════════════════════════════════════════════

  const SSC_SUBJECT_NAMES = {
    "101": "Bangla", "107": "English", "109": "Mathematics",
    "111": "Religion (Islam)", "112": "Religion (Hindu)", "113": "Religion (Buddhist)",
    "114": "Religion (Christian)",
    "154": "ICT", "150": "Bangladesh & Global Studies", "136": "Physics",
    "137": "Chemistry", "138": "Biology", "126": "Higher Mathematics",
    "127": "General Science", "146": "Accounting", "152": "Finance & Banking",
    "143": "Business Entrepreneurship", "151": "Home Science",
  };
  const SSC_GRADE_ORDER = ["A+", "A", "A-", "B", "C", "D", "F"];
  const SSC_SCIENCE_ORDER = ["101", "107", "109", "150", "111", "112", "113", "136", "137", "138", "126", "154"];
  const SSC_BUSINESS_ORDER = ["101", "107", "109", "127", "111", "112", "113", "146", "152", "143", "154", "151"];
  const SSC_COMBINED_ORDER = ["101", "107", "109", "154", "111", "112", "113", "150", "136", "137", "138", "126",
                               "127", "146", "152", "143", "151"];

  let _sscPdfFile = null;
  let _sscRosterFile = null;

  function loadSscResultAnalysisView() {
    _setViewHash('ssc_result_analysis');
    setActiveNavLink('nav-ssc-result-analysis');
    setContentHeader('Analyse SSC Result', 'file-bar-chart');
    const container = document.getElementById('view-container');
    if (!container) return;
    _sscPdfFile = null;
    _sscRosterFile = null;
    container.innerHTML = `
      <div class="max-w-3xl mx-auto bg-white p-8 rounded-3xl shadow-2xl border border-slate-100">
        <h2 class="text-2xl font-black text-slate-800 tracking-tight mb-1">Analyse SSC Result</h2>
        <p class="text-xs text-slate-400 font-bold uppercase tracking-widest mb-6">
          Upload a board result PDF to generate an aggregated-by-roll Excel workbook — runs entirely
          in your browser, nothing is uploaded to a server.
        </p>

        <div class="space-y-5">
          <div>
            <label class="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">
              1. Result PDF <span class="text-red-500">*</span>
            </label>
            <input type="file" id="sscPdfInput" accept=".pdf" onchange="handleSscPdfFile(event)"
                   class="w-full text-xs font-bold file:mr-3 file:py-2.5 file:px-4 file:rounded-xl file:border-0
                          file:bg-blue-50 file:text-blue-600 file:font-black file:text-[10px] file:uppercase
                          file:tracking-widest hover:file:bg-blue-100 transition-all">
            <p id="sscPdfStatus" class="text-xs text-slate-400 font-bold mt-1.5"></p>
          </div>

          <div>
            <label class="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">
              2. Student Roster .docx <span class="text-slate-300 normal-case font-bold">(optional — adds Name / Section / Version)</span>
            </label>
            <input type="file" id="sscRosterInput" accept=".docx" onchange="handleSscRosterFile(event)"
                   class="w-full text-xs font-bold file:mr-3 file:py-2.5 file:px-4 file:rounded-xl file:border-0
                          file:bg-slate-100 file:text-slate-600 file:font-black file:text-[10px] file:uppercase
                          file:tracking-widest hover:file:bg-slate-200 transition-all">
            <p id="sscRosterStatus" class="text-xs text-slate-400 font-bold mt-1.5"></p>
          </div>

          <button onclick="generateSscResultExcel()"
                  class="w-full bg-blue-600 text-white font-black px-6 py-4 rounded-2xl hover:bg-black
                         transition-all text-xs uppercase tracking-widest shadow-xl shadow-blue-500/20
                         flex items-center justify-center gap-2">
            <i data-lucide="file-spreadsheet" class="h-4 w-4"></i> Generate Excel Workbook
          </button>

          <div id="sscStatusBox" class="hidden rounded-2xl p-4 bg-slate-50 border border-slate-200">
            <p id="sscStatus" class="text-xs font-bold text-slate-600"></p>
          </div>
        </div>
      </div>
    `;
    if (typeof lucide !== 'undefined') lucide.createIcons();
  }

  function handleSscPdfFile(e) {
    _sscPdfFile = e.target.files[0] || null;
    const status = document.getElementById('sscPdfStatus');
    if (status) status.textContent = _sscPdfFile ? _sscPdfFile.name : '';
  }

  function handleSscRosterFile(e) {
    _sscRosterFile = e.target.files[0] || null;
    const status = document.getElementById('sscRosterStatus');
    if (status) status.textContent = _sscRosterFile ? _sscRosterFile.name : '';
  }

  function _sscSetStatus(msg, isError) {
    const box = document.getElementById('sscStatusBox');
    const p = document.getElementById('sscStatus');
    if (box) box.classList.remove('hidden');
    if (p) { p.textContent = msg; p.className = 'text-xs font-bold ' + (isError ? 'text-red-500' : 'text-slate-600'); }
  }

  function ensurePDFJS() {
    if (window.pdfjsLib) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const sc = document.createElement('script');
      sc.src = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js';
      sc.onload = () => {
        window.pdfjsLib.GlobalWorkerOptions.workerSrc =
          'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
        resolve();
      };
      sc.onerror = () => reject(new Error('Could not load the PDF reader — check your connection and retry.'));
      document.head.appendChild(sc);
    });
  }

  function ensureSscJSZip() {
    if (window.JSZip) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const sc = document.createElement('script');
      sc.src = 'https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';
      sc.onload = resolve;
      sc.onerror = () => reject(new Error('Could not load the DOCX reader — check your connection and retry.'));
      document.head.appendChild(sc);
    });
  }

  function _sscExtractPdfText(file) {
    return file.arrayBuffer().then(buf =>
      window.pdfjsLib.getDocument({ data: new Uint8Array(buf) }).promise
    ).then(async (pdf) => {
      let fullText = '';
      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const tc = await page.getTextContent();
        const items = tc.items.map(it => ({ str: it.str, x: it.transform[4], y: it.transform[5] }));
        const lines = {};
        for (const it of items) { const key = Math.round(it.y); (lines[key] = lines[key] || []).push(it); }
        const sortedKeys = Object.keys(lines).map(Number).sort((a, b) => b - a);
        fullText += sortedKeys.map(k => lines[k].sort((a, b) => a.x - b.x).map(it => it.str).join('')).join('\n') + '\n';
      }
      return fullText;
    });
  }

  function _sscParseRosterDocx(file) {
    return file.arrayBuffer().then(buf => window.JSZip.loadAsync(buf)).then(zip =>
      zip.file('word/document.xml').async('string')
    ).then(xmlText => {
      const tblMatch = xmlText.match(/<w:tbl>[\s\S]*?<\/w:tbl>/);
      if (!tblMatch) throw new Error('No table found in the roster document.');
      const rowMatches = [...tblMatch[0].matchAll(/<w:tr\b[\s\S]*?<\/w:tr>/g)];
      return rowMatches.map(rm => {
        const cellMatches = [...rm[0].matchAll(/<w:tc\b[\s\S]*?<\/w:tc>/g)];
        return cellMatches.map(cm => [...cm[0].matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)].map(t => t[1]).join(''));
      });
    });
  }

  function sscParseHeader(text) {
    const header = {};
    let m = text.match(/INSTITUTE NAME\s*:\s*(.+?)\((\d+)\)/);
    if (m) { header.institution = m[1].trim(); header.eiin = m[2]; }
    m = text.match(/Institution:\s*(.+?)\s*\(EIIN:\s*(\d+)\)/);
    if (m) { header.institution = m[1].trim(); header.eiin = m[2]; }
    m = text.match(/RESULTS? OF SSC EXAMINATION,\s*(\d{4})/);
    if (m) header.year = m[1];
    m = text.match(/APP\s*:\s*(\d+)/);
    if (m) header.app = m[1];
    m = text.match(/PASS\s*:\s*(\d+)/);
    if (m) header.pass = m[1];
    m = text.match(/GPA5\s*:\s*(\d+)/);
    if (m) header.gpa5 = m[1];
    m = text.match(/Examinee:\s*(\d+),\s*Appeared:\s*(\d+),\s*Passed:\s*(\d+),\s*Percentage of Pass:\s*([\d.]+),\s*GPA 5:\s*(\d+)/);
    if (m) { header.examinee = m[1]; header.app = m[2]; header.pass = m[3]; header.percent = m[4]; header.gpa5 = m[5]; }
    return header;
  }

  function sscDetectFormat(text) {
    if (/\d{4,7}\[[^\]]+\]:\d+:T:\d+\(/.test(text)) return 'detailed';
    if (/\d{4,7}\[[^\]]+\]\s*,/.test(text) || /\d{4,7}\[[^\]]+\]\s*$/m.test(text)) return 'simple';
    return 'unknown';
  }

  function sscParseDetailed(text) {
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    let group = null;
    const records = {};
    const lineRe = /^(\d{4,7})\[([^\]]+)\]:(.*)$/;
    const absRe = /^(\d{4,7})\[([^\]]+)\]\s*$/;
    for (const line of lines) {
      if (line.includes('UNSUCCESSFUL')) { group = 'UNSUCCESSFUL/OTHERS'; continue; }
      if (line.endsWith(':') && (line === line.toUpperCase() || line.includes('STUDIES'))) {
        if (!line.includes('EXAMINEES')) group = line.replace(/:$/, '').trim();
        continue;
      }
      let m = line.match(lineRe);
      if (m) {
        const [, roll, gpa, rest] = m;
        const subjects = {};
        for (const part of rest.split(',')) {
          const pm = part.trim().match(/(\d+):T:(\d+)\(([^)]+)\)/);
          if (pm) subjects[pm[1]] = [pm[2].trim(), pm[3].trim()];
        }
        records[roll] = { group, gpa, status: 'PASS', subjects };
        continue;
      }
      m = line.match(absRe);
      if (m) records[m[1]] = { group, gpa: '', status: m[2].replace(/\.$/, ''), subjects: {} };
    }
    return records;
  }

  function sscParseSimple(text) {
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    let group = null;
    const records = {};
    for (const line of lines) {
      if (line.includes('BUSINESS STUDIES') && /^-+\s*:/.test(line)) { group = 'BUSINESS STUDIES'; continue; }
      if (line.includes('SCIENCE') && /^-+\s*:/.test(line) && !line.includes('BUSINESS')) { group = 'SCIENCE'; continue; }
      if (line.includes('HUMANITIES') && /^-+\s*:/.test(line)) { group = 'HUMANITIES'; continue; }
      if (line.includes('END OF RESULT')) { group = null; continue; }
      if (group && /\d{4,7}\[/.test(line)) {
        const cleaned = line.replace(/=\d+/g, '');
        const re = /(\d{4,7})\[([^\]]+)\]/g;
        let mm;
        while ((mm = re.exec(cleaned)) !== null) {
          const [, roll, gpaRaw] = mm;
          const gpa = gpaRaw.trim();
          const status = /^[\d.]+$/.test(gpa) ? 'PASS' : gpa.replace(/\.$/, '');
          records[roll] = { group, gpa: status === 'PASS' ? gpa : '', status, subjects: {} };
        }
      }
    }
    return records;
  }

  function sscParseRosterRows(rows) {
    if (!rows || !rows.length) return {};
    const headerCells = rows[0].map(h => String(h || '').toLowerCase());
    const findCol = (...keywords) => {
      for (let i = 0; i < headerCells.length; i++) {
        if (keywords.every(k => headerCells[i].includes(k))) return i;
      }
      return null;
    };
    const colName = findCol('name');
    const colRoll = findCol('class') !== null ? findCol('class') : findCol('roll');
    const colSec = findCol('sec');
    const colReg = findCol('registration');
    const colSsc = findCol('ssc', 'roll');
    const colVer = findCol('version');
    const colGender = findCol('gender');
    const roster = {};
    for (let i = 1; i < rows.length; i++) {
      const cells = rows[i];
      if (colSsc === null || colSsc >= cells.length) continue;
      const sscRoll = String(cells[colSsc] || '').trim();
      if (!sscRoll) continue;
      roster[sscRoll] = {
        name: colName !== null ? (cells[colName] || '') : '',
        classRoll: colRoll !== null ? (cells[colRoll] || '') : '',
        section: colSec !== null ? (cells[colSec] || '') : '',
        regNo: colReg !== null ? (cells[colReg] || '') : '',
        version: colVer !== null ? (cells[colVer] || '') : '',
        gender: colGender !== null ? (cells[colGender] || '') : '',
      };
    }
    return roster;
  }

  function sscGpaBand(gpa) {
    if (gpa === '' || gpa === null || gpa === undefined) return 'F';
    const g = parseFloat(gpa);
    if (g === 5.0) return '5.00';
    if (g >= 4.0 && g < 5.0) return '4-5';
    if (g >= 3.5 && g < 4.0) return '3.5-4';
    if (g >= 3.0 && g < 3.5) return '3-3.5';
    if (g >= 2.0 && g < 3.0) return '2-3';
    if (g >= 1.0 && g < 2.0) return '1-2';
    return 'F';
  }

  function sscRound2(n) { return Math.round(n * 100) / 100; }
  function sscPct(n, total) { return total ? sscRound2((n / total) * 100).toFixed(2) : '-'; }
  function sscDash(n) { return n ? String(n) : '-'; }

  function sscBuildSheets(records, roster, header) {
    const fmt = Object.values(records).some(r => Object.keys(r.subjects).length) ? 'detailed' : 'simple';
    const allCodes = fmt === 'detailed'
      ? [...new Set(Object.values(records).flatMap(r => Object.keys(r.subjects)))].sort((a, b) => +a - +b)
      : [];
    const allRolls = Object.keys(records).sort((a, b) => +a - +b);
    const haveVersion = Object.values(roster).some(v => v.version);
    const sheets = [];

    const aggHeaders = ['SSC Roll', 'Name', 'Class Roll', 'Section', 'Registration No', 'Version', 'Gender',
                         'Group', 'GPA', 'Status'];
    const subjHeaders = [];
    for (const code of allCodes) {
      const label = SSC_SUBJECT_NAMES[code] || `Subject ${code}`;
      subjHeaders.push(`${label} (${code}) Mark`, `${label} (${code}) Grade`);
    }
    const aggRows = [aggHeaders.concat(subjHeaders)];
    for (const roll of allRolls) {
      const rec = records[roll];
      const ros = roster[roll] || {};
      const row = [roll, ros.name || '', ros.classRoll || '', ros.section || '', ros.regNo || '',
                   ros.version || '', ros.gender || '', rec.group || '', rec.gpa, rec.status];
      for (const code of allCodes) {
        const s = rec.subjects[code];
        row.push(s ? s[0] : '', s ? s[1] : '');
      }
      aggRows.push(row);
    }
    sheets.push({ name: 'Aggregated Result', rows: aggRows });

    const bucket = () => ({ total: 0, gpa5: 0, pass: 0, abs: 0 });
    const gv = {}, gStats = {};
    for (const roll of allRolls) {
      const rec = records[roll];
      const ros = roster[roll] || {};
      const g = rec.group || 'Unknown';
      const ver = haveVersion ? (ros.version === 'EV' ? 'English' : 'Bangla') : '-';
      for (const [store, key] of [[gStats, g], [gv, g + '|' + ver]]) {
        const b = store[key] = store[key] || bucket();
        b.total++;
        if (rec.status === 'PASS') { b.pass++; if (parseFloat(rec.gpa) === 5.0) b.gpa5++; }
        else b.abs++;
      }
    }
    const knownGroups = Object.keys(gStats).filter(g => g !== 'UNSUCCESSFUL/OTHERS' && g !== 'Unknown');
    const sumRows = [['Group', 'Version', 'Registered', 'Appeared', 'Pass', 'GPA-5', 'Absent']];
    for (const g of knownGroups) {
      if (haveVersion) {
        for (const ver of ['Bangla', 'English']) {
          const v = gv[g + '|' + ver];
          if (v) sumRows.push([g, ver, v.total, v.total - v.abs, v.pass, v.gpa5, v.abs]);
        }
        const t = gStats[g];
        sumRows.push([g, 'Total', t.total, t.total - t.abs, t.pass, t.gpa5, t.abs]);
      } else {
        const t = gStats[g];
        sumRows.push([g, '-', t.total, t.total - t.abs, t.pass, t.gpa5, t.abs]);
      }
    }
    for (const [g, t] of Object.entries(gStats)) {
      if (knownGroups.includes(g)) continue;
      sumRows.push([g, '-', t.total, t.total - t.abs, t.pass, t.gpa5, t.abs]);
    }
    const grand = bucket();
    for (const t of Object.values(gStats)) { grand.total += t.total; grand.pass += t.pass; grand.gpa5 += t.gpa5; grand.abs += t.abs; }
    sumRows.push(['TOTAL', '', grand.total, grand.total - grand.abs, grand.pass, grand.gpa5, grand.abs]);
    sheets.push({ name: 'Summary', rows: sumRows });

    const legendRows = [['Code', 'Subject Name']];
    if (allCodes.length) allCodes.forEach(c => legendRows.push([c, SSC_SUBJECT_NAMES[c] || 'Unknown']));
    else legendRows.push(['-', 'No subject codes available -- this PDF only lists Roll + GPA, no subject-wise marks.']);
    sheets.push({ name: 'Subject Code Legend', rows: legendRows });

    const subjStats = {};
    allCodes.forEach(c => subjStats[c] = { marks: [], grades: {} });
    for (const rec of Object.values(records)) {
      for (const [code, [mark, grade]] of Object.entries(rec.subjects)) {
        if (mark) subjStats[code].marks.push(+mark);
        if (grade) subjStats[code].grades[grade] = (subjStats[code].grades[grade] || 0) + 1;
      }
    }
    const swsRows = [['Code', 'Subject Name', 'Appeared', 'Highest Mark', 'Lowest Mark', 'Average Mark'].concat(SSC_GRADE_ORDER)];
    if (allCodes.length) {
      for (const code of allCodes) {
        const st = subjStats[code];
        const appeared = st.marks.length;
        const row = [code, SSC_SUBJECT_NAMES[code] || `Subject ${code}`, appeared,
                     appeared ? Math.max(...st.marks) : '', appeared ? Math.min(...st.marks) : '',
                     appeared ? sscRound2(st.marks.reduce((a, b) => a + b, 0) / appeared) : ''];
        SSC_GRADE_ORDER.forEach(g => row.push(st.grades[g] || 0));
        swsRows.push(row);
      }
    } else {
      swsRows.push(['-', 'No subject-wise mark data available in this PDF format.']);
    }
    sheets.push({ name: 'Subject-wise Summary', rows: swsRows });

    const swvRows = [['Code', 'Subject Name', 'Group', 'Version', 'Appeared', 'Highest Mark', 'Lowest Mark', 'Average Mark'].concat(SSC_GRADE_ORDER)];
    if (allCodes.length && haveVersion) {
      const verStats = {};
      for (const roll of allRolls) {
        const rec = records[roll];
        if (!knownGroups.includes(rec.group)) continue;
        const ros = roster[roll] || {};
        const verLabel = ros.version === 'EV' ? 'English' : 'Bangla';
        for (const [code, [mark, grade]] of Object.entries(rec.subjects)) {
          if (!grade) continue;
          const key = code + '|' + rec.group + '|' + verLabel;
          const st = verStats[key] = verStats[key] || { marks: [], grades: {} };
          if (mark) st.marks.push(+mark);
          st.grades[grade] = (st.grades[grade] || 0) + 1;
        }
      }
      const codeGroups = {};
      Object.keys(verStats).forEach(k => {
        const [code, grp] = k.split('|');
        (codeGroups[code] = codeGroups[code] || new Set()).add(grp);
      });
      const bs = (marks, grades) => {
        const appeared = marks.length;
        return [appeared, appeared ? Math.max(...marks) : '', appeared ? Math.min(...marks) : '',
                appeared ? sscRound2(marks.reduce((a, b) => a + b, 0) / appeared) : ''];
      };
      for (const code of allCodes) {
        const groupsPresent = [...(codeGroups[code] || [])].sort();
        if (!groupsPresent.length) continue;
        let overallMarks = [], overallGrades = {};
        for (const grp of groupsPresent) {
          let cMarks = [], cGrades = {};
          for (const ver of ['Bangla', 'English']) {
            const st = verStats[code + '|' + grp + '|' + ver];
            if (!st) continue;
            const [appeared, hi, lo, avg] = bs(st.marks, st.grades);
            const row = [code, SSC_SUBJECT_NAMES[code] || `Subject ${code}`,
                         grp.charAt(0) + grp.slice(1).toLowerCase(), ver, appeared, hi, lo, avg];
            SSC_GRADE_ORDER.forEach(g => row.push(st.grades[g] || 0));
            swvRows.push(row);
            cMarks = cMarks.concat(st.marks);
            for (const [g, n] of Object.entries(st.grades)) cGrades[g] = (cGrades[g] || 0) + n;
          }
          const [appeared, hi, lo, avg] = bs(cMarks, cGrades);
          const row = [code, SSC_SUBJECT_NAMES[code] || `Subject ${code}`,
                       grp.charAt(0) + grp.slice(1).toLowerCase(), 'Total', appeared, hi, lo, avg];
          SSC_GRADE_ORDER.forEach(g => row.push(cGrades[g] || 0));
          swvRows.push(row);
          overallMarks = overallMarks.concat(cMarks);
          for (const [g, n] of Object.entries(cGrades)) overallGrades[g] = (overallGrades[g] || 0) + n;
        }
        if (groupsPresent.length > 1) {
          const [appeared, hi, lo, avg] = bs(overallMarks, overallGrades);
          const row = [code, SSC_SUBJECT_NAMES[code] || `Subject ${code}`, 'Overall (Both Groups)', 'Total', appeared, hi, lo, avg];
          SSC_GRADE_ORDER.forEach(g => row.push(overallGrades[g] || 0));
          swvRows.push(row);
        }
      }
    } else if (!allCodes.length) {
      swvRows.push(['-', 'No subject-wise mark data available in this PDF format.']);
    } else {
      swvRows.push(['-', 'No Version data available -- provide a student roster .docx with a Version column to enable this breakdown.']);
    }
    sheets.push({ name: 'Subject-wise by Version', rows: swvRows });

    sheets.push({ name: 'Report Analysis', rows: _sscBuildReportAnalysis(records, roster, header, allCodes, knownGroups, gStats, gv, haveVersion) });

    return { sheets, fmt };
  }

  function _sscBuildReportAnalysis(records, roster, header, allCodes, knownGroups, gStats, gv, haveVersion) {
    const rows = [];
    const sec = (title) => { rows.push([]); rows.push([title]); };
    const inst = header.institution || 'Institution';
    const year = header.year || '';
    rows.push([`SSC Result Summary ${year} -- ${inst}`]);

    sec('1. SSC RESULT SUMMARY');
    rows.push(['Group', 'Examinee', 'Passed', '% of Pass', 'GPA-5.00', '4<5', '3.5<4', '3<3.5', '2<3', '1<2', 'F']);
    const bandsOf = (g) => {
      const rec = {};
      for (const roll of Object.keys(records)) {
        const r = records[roll];
        if (r.group !== g) continue;
        const b = r.status === 'PASS' ? sscGpaBand(r.gpa) : 'F';
        rec[b] = (rec[b] || 0) + 1;
      }
      return rec;
    };
    let grandEx = 0, grandPass = 0, grandBands = {};
    for (const g of knownGroups) {
      const t = gStats[g];
      const bands = bandsOf(g);
      rows.push([g, t.total, t.pass, sscPct(t.pass, t.total), sscDash(bands['5.00']), sscDash(bands['4-5']),
                 sscDash(bands['3.5-4']), sscDash(bands['3-3.5']), sscDash(bands['2-3']), sscDash(bands['1-2']), sscDash(bands['F'])]);
      grandEx += t.total; grandPass += t.pass;
      for (const [k, v] of Object.entries(bands)) grandBands[k] = (grandBands[k] || 0) + v;
    }
    rows.push(['TOTAL', grandEx, grandPass, sscPct(grandPass, grandEx), sscDash(grandBands['5.00']), sscDash(grandBands['4-5']),
               sscDash(grandBands['3.5-4']), sscDash(grandBands['3-3.5']), sscDash(grandBands['2-3']), sscDash(grandBands['1-2']), sscDash(grandBands['F'])]);

    sec('2. VERSION-WISE RESULT ANALYSIS');
    if (haveVersion) {
      for (const g of knownGroups) {
        rows.push([g]);
        rows.push(['Version', 'GPA-5.00', '4<5', '3.5<4', '3<3.5', '2<3', '1<2', 'F', 'Total']);
        let gt = { '5.00': 0, '4-5': 0, '3.5-4': 0, '3-3.5': 0, '2-3': 0, '1-2': 0, 'F': 0, total: 0 };
        for (const ver of ['Bangla', 'English']) {
          const v = gv[g + '|' + ver];
          if (!v) continue;
          const bands = {};
          for (const roll of Object.keys(records)) {
            const r = records[roll]; if (r.group !== g) continue;
            const ros = roster[roll] || {};
            const rv = ros.version === 'EV' ? 'English' : 'Bangla';
            if (rv !== ver) continue;
            const b = r.status === 'PASS' ? sscGpaBand(r.gpa) : 'F';
            bands[b] = (bands[b] || 0) + 1;
          }
          rows.push([ver, sscDash(bands['5.00']), sscDash(bands['4-5']), sscDash(bands['3.5-4']), sscDash(bands['3-3.5']),
                     sscDash(bands['2-3']), sscDash(bands['1-2']), sscDash(bands['F']), v.total]);
          for (const k of Object.keys(gt)) if (k !== 'total') gt[k] += (bands[k] || 0);
          gt.total += v.total;
        }
        rows.push(['Total', sscDash(gt['5.00']), sscDash(gt['4-5']), sscDash(gt['3.5-4']), sscDash(gt['3-3.5']),
                   sscDash(gt['2-3']), sscDash(gt['1-2']), sscDash(gt['F']), gt.total]);
        rows.push([]);
      }
    } else {
      rows.push(['No Version data available -- provide a student roster .docx with a Version column to enable this breakdown.']);
    }

    sec('3. SUBJECT-WISE LETTER GRADE');
    if (allCodes.length) {
      const gradeStatsByGroup = {};
      for (const rec of Object.values(records)) {
        if (!knownGroups.includes(rec.group)) continue;
        for (const [code, [mark, grade]] of Object.entries(rec.subjects)) {
          if (!grade) continue;
          const gg = gradeStatsByGroup[rec.group] = gradeStatsByGroup[rec.group] || {};
          const cc = gg[code] = gg[code] || { total: 0, grades: {} };
          cc.total++;
          cc.grades[grade] = (cc.grades[grade] || 0) + 1;
        }
      }
      const orderFor = (g) => g === 'SCIENCE' ? SSC_SCIENCE_ORDER : g === 'BUSINESS STUDIES' ? SSC_BUSINESS_ORDER : allCodes;
      for (const g of knownGroups) {
        rows.push([g]);
        rows.push(['Subject', 'A+', 'A', 'A-', 'B', 'C', 'D', 'Total']);
        for (const code of orderFor(g)) {
          const cc = (gradeStatsByGroup[g] || {})[code];
          if (!cc) continue;
          rows.push([SSC_SUBJECT_NAMES[code] || `Subject ${code}`, sscDash(cc.grades['A+']), sscDash(cc.grades['A']),
                     sscDash(cc.grades['A-']), sscDash(cc.grades['B']), sscDash(cc.grades['C']), sscDash(cc.grades['D']), cc.total]);
        }
        rows.push([]);
      }
    } else {
      rows.push(['No subject-wise mark data available in this PDF format.']);
    }

    sec('4. SUBJECT-WISE A+ (ALL GROUPS COMBINED)');
    if (allCodes.length) {
      rows.push(['Subject', 'Total Students', 'A+', '%']);
      const allGrades = {};
      for (const rec of Object.values(records)) {
        for (const [code, [mark, grade]] of Object.entries(rec.subjects)) {
          if (!grade) continue;
          const cc = allGrades[code] = allGrades[code] || { total: 0, aplus: 0 };
          cc.total++;
          if (grade === 'A+') cc.aplus++;
        }
      }
      for (const code of SSC_COMBINED_ORDER) {
        const cc = allGrades[code];
        if (!cc) continue;
        rows.push([SSC_SUBJECT_NAMES[code] || `Subject ${code}`, cc.total, cc.aplus, sscPct(cc.aplus, cc.total)]);
      }
    } else {
      rows.push(['No subject-wise mark data available in this PDF format.']);
    }

    return rows;
  }

  function generateSscResultExcel() {
    if (!_sscPdfFile) { showToast('Please choose a result PDF first', 'error'); return; }
    _sscSetStatus('Loading PDF engine…');
    let text, header, fmt, records, roster = {};
    ensurePDFJS()
      .then(() => { _sscSetStatus('Reading PDF…'); return _sscExtractPdfText(_sscPdfFile); })
      .then(t => {
        text = t;
        header = sscParseHeader(text);
        fmt = sscDetectFormat(text);
        if (fmt === 'unknown') throw new Error('This PDF layout was not recognized as a BISE-style result printout.');
        records = fmt === 'detailed' ? sscParseDetailed(text) : sscParseSimple(text);
        _sscSetStatus(`Parsed ${Object.keys(records).length} roll entries (${fmt} format).`);
        if (_sscRosterFile) {
          _sscSetStatus('Reading roster…');
          return ensureSscJSZip().then(() => _sscParseRosterDocx(_sscRosterFile)).then(rows => {
            roster = sscParseRosterRows(rows);
          });
        }
      })
      .then(() => { _sscSetStatus('Building Excel workbook…'); return ensureXLSX(); })
      .then(() => {
        const { sheets } = sscBuildSheets(records, roster, header);
        const wb = XLSX.utils.book_new();
        for (const s of sheets) {
          const ws = XLSX.utils.aoa_to_sheet(s.rows);
          XLSX.utils.book_append_sheet(wb, ws, s.name.slice(0, 31));
        }
        const nameBits = [(header.institution || 'SSC-Result').replace(/\s+/g, '-'), header.year || ''].filter(Boolean);
        const fileName = nameBits.join('-') + '-Aggregated.xlsx';
        XLSX.writeFile(wb, fileName);
        _sscSetStatus('Done — ' + fileName + ' downloaded.');
        showToast('Excel workbook generated', 'success');
      })
      .catch(err => {
        console.error(err);
        _sscSetStatus('Error: ' + err.message, true);
        showToast(err.message, 'error');
      });
  }
